'use client';

import { useEffect, useState, useMemo } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Skeleton } from '@/components/ui/skeleton';
import { ScoreCard } from '@/components/ScoreCard';
import { DimensionCard } from '@/components/DimensionCard';
import { MarketOverview } from '@/components/MarketOverview';
import { NewsSection } from '@/components/NewsSection';
import { SymbolData, computeSymbolScore, getScoreColor, SymbolScore, DimensionScore } from '@/lib/scoring';
import { adaptSymbolItems, adaptIndex, adaptGoldCurrency, type BRSSymbolItem, type BRSGoldCurrencyItem } from '@/lib/data-adapter';
import { MOCK_SYMBOLS, MOCK_INDICES, MOCK_GOLD_CURRENCY, MOCK_NEWS, getTopGainers, getTopLosers } from '@/lib/mock-data';
import { TrendingUp, TrendingDown, BarChart3, Wifi, WifiOff, Trophy, AlertOctagon, Network } from 'lucide-react';
import { SymbolHoverCard } from '@/components/SymbolHoverCard';
import { IndexTrend } from '@/components/IndexTrend';
import { ProgressDynamic } from '@/components/ui/progress-dynamic';
import { HierarchyExplorer } from '@/components/HierarchyExplorer';
import { Button } from '@/components/ui/button';

interface NewsItem {
  title: string;
  source: string;
  time: string;
  url: string;
}

interface DashboardTabProps {
  onSymbolClick: (symbol: SymbolData, score: SymbolScore) => void;
}

function formatTimeAgo(dateStr: string): string {
  try {
    const diff = Date.now() - new Date(dateStr).getTime();
    const hours = Math.floor(diff / 3600000);
    if (hours < 1) return 'کمتر از یک ساعت پیش';
    if (hours < 24) return `${hours} ساعت پیش`;
    return `${Math.floor(hours / 24)} روز پیش`;
  } catch {
    return dateStr;
  }
}

export function DashboardTab({ onSymbolClick }: DashboardTabProps) {
  const [symbols, setSymbols] = useState<SymbolData[]>([]);
  const [indices, setIndices] = useState(MOCK_INDICES);
  const [goldCurrency, setGoldCurrency] = useState(MOCK_GOLD_CURRENCY);
  const [news, setNews] = useState<NewsItem[]>(MOCK_NEWS);
  const [loading, setLoading] = useState(true);
  const [dataSource, setDataSource] = useState<'brs-api' | 'fallback'>('fallback');
  const [explorerOpen, setExplorerOpen] = useState(false);

  useEffect(() => {
    let cancelled = false;

    async function fetchData() {
      try {
        const [marketRes, indicesRes, newsRes, goldRes] = await Promise.allSettled([
          fetch('/api/market'),
          fetch('/api/indices'),
          fetch('/api/news'),
          fetch('/api/gold-currency'),
        ]);

        if (cancelled) return;

        // Parse market data
        if (marketRes.status === 'fulfilled' && marketRes.value.ok) {
          const data = await marketRes.value.json();

          const rawSymbols = data?.data?.symbols || data?.symbols || [];
          // Track data source
          if (data?.meta?.source === 'brs-api' || data?.data?.dataSource === 'brs-api') {
            setDataSource('brs-api');
          }
          if (rawSymbols.length > 0) {
            const adapted = adaptSymbolItems(rawSymbols as BRSSymbolItem[]);
            if (adapted.length > 0) {
              setSymbols(adapted);
            }
          }
        }

        // Parse indices
        if (indicesRes.status === 'fulfilled' && indicesRes.value.ok) {
          const data = await indicesRes.value.json();
          const rawIndices = data?.data || data?.indices || [];
          if (Array.isArray(rawIndices) && rawIndices.length > 0) {
            setIndices(rawIndices.map(adaptIndex));
          }
        }

        // Parse news
        if (newsRes.status === 'fulfilled' && newsRes.value.ok) {
          const data = await newsRes.value.json();
          const rawNews = data?.data || [];
          if (Array.isArray(rawNews) && rawNews.length > 0) {
            setNews(rawNews.map((n: { title?: string; source?: string; date?: string; url?: string; snippet?: string }) => ({
              title: n.title || '',
              source: n.source || '',
              time: n.date ? formatTimeAgo(n.date) : '',
              url: n.url || '#',
            })));
          }
        }

        // Parse gold/currency
        if (goldRes.status === 'fulfilled' && goldRes.value.ok) {
          const data = await goldRes.value.json();
          const gcData = data?.data;
          const rawGold = gcData?.all || gcData?.gold || (Array.isArray(gcData) ? gcData : []);
          if (Array.isArray(rawGold) && rawGold.length > 0) {
            setGoldCurrency(rawGold.map((g: BRSGoldCurrencyItem) => adaptGoldCurrency(g)));
          }
        }
      } catch {
        // Use mock data as fallback
      } finally {
        if (!cancelled) {
          setSymbols(prev => prev.length > 0 ? prev : MOCK_SYMBOLS);
          setLoading(false);
        }
      }
    }
    fetchData();
    return () => { cancelled = true; };
  }, []);

  // Compute scores for all symbols
  const marketChange = indices[0]?.changePercent || 0;
  const scoredSymbols = useMemo(() => {
    return symbols.map(s => ({
      data: s,
      score: computeSymbolScore(s, marketChange),
    }));
  }, [symbols, marketChange]);

  // Average total score
  const avgScore = useMemo(() => {
    if (scoredSymbols.length === 0) return 0;
    return Math.round(scoredSymbols.reduce((sum, s) => sum + s.score.totalScore, 0) / scoredSymbols.length);
  }, [scoredSymbols]);

  // Average dimensions
  const avgDimensions = useMemo(() => {
    if (scoredSymbols.length === 0) return [];
    const dimCount = 6;
    const avgs: Array<DimensionScore & { color: string }> = [];
    
    for (let i = 0; i < dimCount; i++) {
      const dimSum = scoredSymbols.reduce((sum, s) => sum + s.score.dimensions[i].score, 0);
      const dim = scoredSymbols[0]?.score.dimensions[i];
      if (dim) {
        avgs.push({
          ...dim,
          score: Math.round(dimSum / scoredSymbols.length),
          percentage: Math.round(dimSum / scoredSymbols.length),
          color: getScoreColor(Math.round(dimSum / scoredSymbols.length)),
        });
      }
    }
    return avgs;
  }, [scoredSymbols]);

  const topGainers = useMemo(() => getTopGainers(symbols), [symbols]);
  const topLosers = useMemo(() => getTopLosers(symbols), [symbols]);

  // Top/Bottom by score
  const topScored = useMemo(() =>
    [...scoredSymbols].sort((a, b) => b.score.totalScore - a.score.totalScore).slice(0, 5),
    [scoredSymbols]
  );
  const bottomScored = useMemo(() =>
    [...scoredSymbols].sort((a, b) => a.score.totalScore - b.score.totalScore).slice(0, 5),
    [scoredSymbols]
  );

  if (loading) {
    return (
      <div className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 grid-gutter-24">
          <Skeleton className="h-48 rounded-xl" />
          <Skeleton className="h-48 rounded-xl" />
          <Skeleton className="h-48 rounded-xl" />
        </div>
        <Skeleton className="h-64 rounded-xl" />
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 grid-gutter-24">
          <Skeleton className="h-48 rounded-xl" />
          <Skeleton className="h-48 rounded-xl" />
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Data Source Indicator + Main Score + Stats Row */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 grid-gutter-24">
        {/* Main Score Card */}
        <Card className="md:col-span-1 card-tarot">
          <CardContent className="flex flex-col items-center justify-center py-8">
            <div className="text-center mb-4">
              <h2 className="text-lg font-semibold text-muted-foreground mb-1">امتیاز کلی بازار</h2>
              <ScoreCard score={avgScore} size="xl" showGauge={true} />
            </div>
            <div className="flex items-center gap-4 mt-2">
              <div className="text-center">
                <div className="text-2xl font-bold text-primary">
                  {new Intl.NumberFormat('fa-IR').format(symbols.length)}
                </div>
                <div className="text-xs text-muted-foreground">تعداد نماد</div>
              </div>
              <div className="h-8 w-px bg-border" />
              <div className="text-center">
                <div className={`text-2xl font-bold ${marketChange >= 0 ? 'text-primary' : 'text-destructive'}`}>
                  {marketChange >= 0 ? '▲' : '▼'}
                  {Math.abs(marketChange).toFixed(2)}%
                </div>
                <div className="text-xs text-muted-foreground">شاخص کل</div>
              </div>
            </div>
            {/* Data Source Badge */}
            <div className="mt-4 flex flex-wrap gap-2 justify-center">
              {dataSource === 'brs-api' ? (
                <Badge variant="default" className="gap-1 text-xs">
                  <Wifi className="size-3" />
                  متصل به BRS API
                </Badge>
              ) : (
                <Badge variant="secondary" className="gap-1 text-xs">
                  <WifiOff className="size-3" />
                  حالت آفلاین
                </Badge>
              )}
              
              <Button 
                variant="outline" 
                size="sm" 
                className="h-7 text-[10px] gap-1.5"
                onClick={() => setExplorerOpen(true)}
              >
                <Network className="size-3" />
                نقشه راه علمی
              </Button>
            </div>
          </CardContent>
        </Card>

        <HierarchyExplorer 
          open={explorerOpen} 
          onClose={() => setExplorerOpen(false)} 
        />

        {/* Top Gainers */}
        <Card className="card-tarot">
          <CardHeader className="pb-2">
            <CardTitle className="text-base font-semibold flex items-center gap-2">
              <TrendingUp className="size-5 text-primary" />
              صعودی‌ترین نمادها
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              {topGainers.map((s, i) => {
                const score = computeSymbolScore(s, marketChange);
                return (
                  <SymbolHoverCard key={s.isin} symbol={s} score={score}>
                    <button
                      data-testid={`top-gainer-${i}`}
                      className="flex items-center justify-between w-full p-2 rounded-lg hover:bg-accent/50 transition-colors text-right duration-300"
                      style={{ transitionTimingFunction: 'cubic-bezier(0.25, 0.1, 0.25, 1.0)' }}
                      onClick={() => onSymbolClick(s, score)}
                    >
                      <div className="flex items-center gap-2">
                        <span className="text-xs text-muted-foreground w-4">{i + 1}</span>
                        <span className="text-sm font-medium">{s.symbol}</span>
                      </div>
                      <div className="flex items-center gap-2">
                        <span className={`text-sm font-bold ${getScoreColor(score.totalScore)}`}>
                          {score.totalScore}
                        </span>
                        <span className="text-xs font-medium text-primary flex items-center gap-0.5">
                          ▲ {s.changePercent.toFixed(2)}%
                        </span>
                      </div>
                    </button>
                  </SymbolHoverCard>
                );
              })}
            </div>
          </CardContent>
        </Card>

        {/* Top Losers */}
        <Card className="card-tarot">
          <CardHeader className="pb-2">
            <CardTitle className="text-base font-semibold flex items-center gap-2">
              <TrendingDown className="size-5 text-destructive" />
              نزولی‌ترین نمادها
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              {topLosers.map((s, i) => {
                const score = computeSymbolScore(s, marketChange);
                return (
                  <SymbolHoverCard key={s.isin} symbol={s} score={score}>
                    <button
                      data-testid={`top-loser-${i}`}
                      className="flex items-center justify-between w-full p-2 rounded-lg hover:bg-accent/50 transition-colors text-right duration-300"
                      style={{ transitionTimingFunction: 'cubic-bezier(0.25, 0.1, 0.25, 1.0)' }}
                      onClick={() => onSymbolClick(s, score)}
                    >
                      <div className="flex items-center gap-2">
                        <span className="text-xs text-muted-foreground w-4">{i + 1}</span>
                        <span className="text-sm font-medium">{s.symbol}</span>
                      </div>
                      <div className="flex items-center gap-2">
                        <span className={`text-sm font-bold ${getScoreColor(score.totalScore)}`}>
                          {score.totalScore}
                        </span>
                        <span className="text-xs font-medium text-destructive flex items-center gap-0.5">
                          ▼ {Math.abs(s.changePercent).toFixed(2)}%
                        </span>
                      </div>
                    </button>
                  </SymbolHoverCard>
                );
              })}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* 6 Dimensions */}
      <Card className="card-tarot">
        <CardHeader>
          <CardTitle className="text-base font-semibold flex items-center gap-2">
            <BarChart3 className="size-5 text-primary" />
            امتیازدهی ۶ بعدی بازار
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-2">
            {avgDimensions.map((dim, i) => (
              <DimensionCard key={dim.key} dimension={dim} index={i} />
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Index Trend Charts */}
      <IndexTrend
        indexValue={indices[0]?.value || 2345678}
        indexChangePercent={indices[0]?.changePercent || 0}
        eqWeightValue={indices[1]?.value || 8765}
        eqWeightChangePercent={indices[1]?.changePercent || 0}
      />

      {/* Top/Bottom Score Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 grid-gutter-24">
        {/* Highest Score */}
        <Card className="card-tarot">
          <CardHeader className="pb-2">
            <CardTitle className="text-base font-semibold flex items-center gap-2">
              <Trophy className="size-5 text-primary" />
              بیشترین صعود امتیاز
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              {topScored.map(({ data: s, score }, i) => {
                const diff = score.totalScore - avgScore;
                return (
                  <SymbolHoverCard key={s.isin} symbol={s} score={score}>
                    <button
                      data-testid={`top-score-${i}`}
                      className="flex items-center justify-between w-full p-2 rounded-lg hover:bg-accent/50 transition-colors text-right duration-300"
                      style={{ transitionTimingFunction: 'cubic-bezier(0.25, 0.1, 0.25, 1.0)' }}
                      onClick={() => onSymbolClick(s, score)}
                    >
                      <div className="flex items-center gap-2">
                        <span className="text-xs text-muted-foreground w-4">{i + 1}</span>
                        <span className="text-sm font-medium">{s.symbol}</span>
                        <span className="text-[10px] text-muted-foreground/60">{s.name}</span>
                      </div>
                      <div className="flex items-center gap-2">
                        <span className={`text-xs font-bold px-1.5 py-0.5 rounded ${diff >= 0 ? 'bg-primary/10 text-primary' : 'bg-destructive/10 text-destructive'}`}>
                          {diff >= 0 ? '▲' : '▼'} {Math.abs(diff)}
                        </span>
                        <span className={`text-sm font-bold ${getScoreColor(score.totalScore)}`}>
                          {score.totalScore}
                        </span>
                        <ProgressDynamic value={score.totalScore} />
                      </div>
                    </button>
                  </SymbolHoverCard>
                );
              })}
            </div>
          </CardContent>
        </Card>

        {/* Lowest Score */}
        <Card className="card-tarot">
          <CardHeader className="pb-2">
            <CardTitle className="text-base font-semibold flex items-center gap-2">
              <AlertOctagon className="size-5 text-destructive" />
              کمترین صعود امتیاز
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              {bottomScored.map(({ data: s, score }, i) => {
                const diff = score.totalScore - avgScore;
                return (
                  <SymbolHoverCard key={s.isin} symbol={s} score={score}>
                    <button
                      data-testid={`bottom-score-${i}`}
                      className="flex items-center justify-between w-full p-2 rounded-lg hover:bg-accent/50 transition-colors text-right duration-300"
                      style={{ transitionTimingFunction: 'cubic-bezier(0.25, 0.1, 0.25, 1.0)' }}
                      onClick={() => onSymbolClick(s, score)}
                    >
                      <div className="flex items-center gap-2">
                        <span className="text-xs text-muted-foreground w-4">{i + 1}</span>
                        <span className="text-sm font-medium">{s.symbol}</span>
                        <span className="text-[10px] text-muted-foreground/60">{s.name}</span>
                      </div>
                      <div className="flex items-center gap-2">
                        <span className={`text-xs font-bold px-1.5 py-0.5 rounded ${diff >= 0 ? 'bg-primary/10 text-primary' : 'bg-destructive/10 text-destructive'}`}>
                          {diff >= 0 ? '▲' : '▼'} {Math.abs(diff)}
                        </span>
                        <span className={`text-sm font-bold ${getScoreColor(score.totalScore)}`}>
                          {score.totalScore}
                        </span>
                        <ProgressDynamic value={score.totalScore} />
                      </div>
                    </button>
                  </SymbolHoverCard>
                );
              })}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Market Overview + News */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 grid-gutter-24">
        <div className="lg:col-span-2">
          <MarketOverview indices={indices} goldCurrency={goldCurrency} />
        </div>
        <div>
          <NewsSection news={news} />
        </div>
      </div>
      

    </div>
  );
}
