'use client';

import type { SymbolScore } from '@/lib/scoring';
import { toPersianNum } from '@/lib/persian';

interface SpiderChartProps {
  score: SymbolScore;
  size?: number;
  showLabels?: boolean;
}

/* ── Colors per dimension ── */
const DIM_COLORS = [
  'var(--chart-5)', // technical - was cyan
  'var(--chart-4)', // fundamental - was emerald  
  'var(--chart-1)', // sentiment - was violet
  'var(--chart-2)', // risk - was amber
  'var(--chart-3)', // macro - was rose
  'var(--secondary)', // board - was sky
];

export function SpiderChart({ score, size = 200, showLabels = true }: SpiderChartProps) {
  const dims = score.dimensions.slice(0, 6);
  const n = dims.length;
  const center = size / 2;
  const maxRadius = showLabels ? size * 0.32 : size * 0.4;
  const labelRadius = maxRadius + 18;

  // Generate polygon points for a given radius
  const getPoints = (radius: number) => {
    return dims.map((_, i) => {
      const angle = (Math.PI * 2 * i) / n - Math.PI / 2;
      return {
        x: center + radius * Math.cos(angle),
        y: center + radius * Math.sin(angle),
      };
    });
  };

  // Grid rings at 25%, 50%, 75%, 100%
  const gridRings = [0.25, 0.5, 0.75, 1.0].map(r => {
    const pts = getPoints(maxRadius * r);
    return pts.map(p => `${p.x},${p.y}`).join(' ');
  });

  // Data polygon
  const dataPoints = dims.map((dim, i) => {
    const angle = (Math.PI * 2 * i) / n - Math.PI / 2;
    const r = (dim.score / 100) * maxRadius;
    return {
      x: center + r * Math.cos(angle),
      y: center + r * Math.sin(angle),
      angle,
    };
  });
  const dataPolygon = dataPoints.map(p => `${p.x},${p.y}`).join(' ');

  // Axis lines
  const axisPoints = getPoints(maxRadius);

  // Label positions
  const labelPositions = dims.map((dim, i) => {
    const angle = (Math.PI * 2 * i) / n - Math.PI / 2;
    const lx = center + labelRadius * Math.cos(angle);
    const ly = center + labelRadius * Math.sin(angle);
    return { x: lx, y: ly, name: dim.name, score: dim.score };
  });

  return (
    <svg
      width={size}
      height={size}
      viewBox={`0 0 ${size} ${size}`}
      className="select-none direction-ltr"
    >
      {/* Grid rings */}
      {gridRings.map((pts, i) => (
        <polygon
          key={`ring-${i}`}
          points={pts}
          fill="none"
          stroke="currentColor"
          strokeOpacity={0.08}
          strokeWidth="1"
        />
      ))}

      {/* Axis lines */}
      {axisPoints.map((pt, i) => (
        <line
          key={`axis-${i}`}
          x1={center}
          y1={center}
          x2={pt.x}
          y2={pt.y}
          stroke="currentColor"
          strokeOpacity={0.08}
          strokeWidth="1"
        />
      ))}

      {/* Filled data area */}
      <polygon
        points={dataPolygon}
        fill="oklch(0.6 0.15 250 / 0.12)"
        stroke="oklch(0.6 0.15 250 / 0.6)"
        strokeWidth="2"
        strokeLinejoin="round"
      />

      {/* Data points */}
      {dataPoints.map((pt, i) => (
        <g key={`dot-${i}`}>
          <circle cx={pt.x} cy={pt.y} r="5" fill={DIM_COLORS[i]} fillOpacity={0.3} />
          <circle cx={pt.x} cy={pt.y} r="3" fill={DIM_COLORS[i]} />
        </g>
      ))}

      {/* Labels */}
      {showLabels && labelPositions.map((lp, i) => {
        // Adjust text anchor based on position
        let textAnchor: "start" | "end" | "middle" = 'middle';
        let dx = 0;
        if (lp.x > center + 5) { textAnchor = 'start'; dx = 4; }
        else if (lp.x < center - 5) { textAnchor = 'end'; dx = -4; }

        return (
          <g key={`label-${i}`}>
            <text
              x={lp.x + dx}
              y={lp.y - 6}
              textAnchor={textAnchor}
              className="fill-foreground"
              fontSize="10"
              fontWeight="700"
              fontFamily="inherit"
            >
              {lp.name}
            </text>
            <text
              x={lp.x + dx}
              y={lp.y + 8}
              textAnchor={textAnchor}
              fill={DIM_COLORS[i]}
              fontSize="11"
              fontWeight="800"
              fontFamily="inherit"
            >
              {toPersianNum(lp.score)}
            </text>
          </g>
        );
      })}
    </svg>
  );
}
