'use client';

import { useEffect, useState, useMemo, useCallback } from 'react';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Skeleton } from '@/components/ui/skeleton';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { SymbolData, computeSymbolScore, getScoreColor, formatPrice, SymbolScore } from '@/lib/scoring';
import { adaptSymbolItems, type BRSSymbolItem } from '@/lib/data-adapter';
import { MOCK_SYMBOLS } from '@/lib/mock-data';
import { Eye, Building, ArrowUpDown, ArrowUp, ArrowDown } from 'lucide-react';
import { SymbolHoverCard } from '@/components/SymbolHoverCard';

interface CompaniesTabProps {
  onSymbolClick: (symbol: SymbolData, score: SymbolScore) => void;
}

type SortField = 'symbol' | 'price' | 'change' | 'changePercent' | 'totalScore';
type SortDir = 'asc' | 'desc';

function SortIcon({ field, sortField, sortDir }: { field: SortField; sortField: SortField; sortDir: SortDir }) {
  if (sortField !== field) return <ArrowUpDown className="size-3 opacity-50" />;
  return sortDir === 'asc' ? <ArrowUp className="size-3" /> : <ArrowDown className="size-3" />;
}

export function CompaniesTab({ onSymbolClick }: CompaniesTabProps) {
  const [symbols, setSymbols] = useState<SymbolData[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [marketFilter, setMarketFilter] = useState('همه');
  const [sortField, setSortField] = useState<SortField>('totalScore');
  const [sortDir, setSortDir] = useState<SortDir>('desc');
  const [page, setPage] = useState(1);
  const pageSize = 50;

  useEffect(() => {
    async function fetchData() {
      try {
        const res = await fetch('/api/market');
        if (res.ok) {
          const data = await res.json();
          const rawSymbols = data?.data?.symbols || data?.symbols || [];
          if (rawSymbols.length > 0) {
            const adapted = adaptSymbolItems(rawSymbols as BRSSymbolItem[]);
            if (adapted.length > 0) {
              setSymbols(adapted);
              setLoading(false);
              return;
            }
          }
        }
      } catch {
        // fallback
      }
      setSymbols(MOCK_SYMBOLS);
      setLoading(false);
    }
    fetchData();
  }, []);

  const scoredSymbols = useMemo(() => {
    return symbols.map(s => ({
      data: s,
      score: computeSymbolScore(s),
    }));
  }, [symbols]);

  const filtered = useMemo(() => {
    let result = scoredSymbols;

    if (marketFilter !== 'همه') {
      result = result.filter(s => s.data.market === marketFilter);
    }

    if (search) {
      const q = search.trim().toLowerCase();
      result = result.filter(
        s =>
          s.data.symbol.toLowerCase().includes(q) ||
          s.data.name.toLowerCase().includes(q) ||
          s.data.isin.toLowerCase().includes(q)
      );
    }

    return result;
  }, [scoredSymbols, marketFilter, search]);

  const sorted = useMemo(() => {
    const arr = [...filtered];
    arr.sort((a, b) => {
      let cmp = 0;
      switch (sortField) {
        case 'symbol':
          cmp = a.data.symbol.localeCompare(b.data.symbol, 'fa');
          break;
        case 'price':
          cmp = a.data.price - b.data.price;
          break;
        case 'change':
          cmp = a.data.change - b.data.change;
          break;
        case 'changePercent':
          cmp = a.data.changePercent - b.data.changePercent;
          break;
        case 'totalScore':
          cmp = a.score.totalScore - b.score.totalScore;
          break;
      }
      return sortDir === 'asc' ? cmp : -cmp;
    });
    return arr;
  }, [filtered, sortField, sortDir]);

  const paginated = useMemo(() => {
    const start = (page - 1) * pageSize;
    return sorted.slice(start, start + pageSize);
  }, [sorted, page]);

  const totalPages = Math.ceil(sorted.length / pageSize);

  const handleSort = useCallback((field: SortField) => {
    setSortDir(prev => prev === 'asc' ? 'desc' : 'asc');
    setSortField(field);
  }, []);

  if (loading) {
    return (
      <div className="space-y-4">
        <Skeleton className="h-12 rounded-lg" />
        <Skeleton className="h-96 rounded-lg" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Filters */}
      <div className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Eye className="absolute right-3 top-1/2 -translate-y-1/2 size-4 text-muted-foreground input-icon" />
          <Input
            placeholder="جستجوی نماد یا نام شرکت..."
            value={search}
            onChange={(e) => { setSearch(e.target.value); setPage(1); }}
            className="input-natural pr-9"
          />
        </div>
        <Select value={marketFilter} onValueChange={(v) => { setMarketFilter(v); setPage(1); }}>
          <SelectTrigger className="w-full sm:w-40">
            <SelectValue placeholder="بازار" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="همه">همه بازارها</SelectItem>
            <SelectItem value="بورس">بورس</SelectItem>
            <SelectItem value="فرابورس">فرابورس</SelectItem>
          </SelectContent>
        </Select>
        <Badge variant="secondary" className="flex items-center gap-1 h-9 px-3">
          <Building className="size-3.5" />
          {new Intl.NumberFormat('fa-IR').format(filtered.length)} نماد
        </Badge>
      </div>

      {/* Table */}
      <Card>
        <CardContent className="p-0">
          <div className="overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="text-right cursor-pointer select-none" onClick={() => handleSort('symbol')}>
                    <div className="flex items-center gap-1">
                      نماد <SortIcon field="symbol" sortField={sortField} sortDir={sortDir} />
                    </div>
                  </TableHead>
                  <TableHead className="text-right hidden md:table-cell">نام شرکت</TableHead>
                  <TableHead className="text-right hidden sm:table-cell">بازار</TableHead>
                  <TableHead className="text-right cursor-pointer select-none" onClick={() => handleSort('price')}>
                    <div className="flex items-center gap-1">
                      قیمت <SortIcon field="price" sortField={sortField} sortDir={sortDir} />
                    </div>
                  </TableHead>
                  <TableHead className="text-right cursor-pointer select-none" onClick={() => handleSort('changePercent')}>
                    <div className="flex items-center gap-1">
                      تغییر <SortIcon field="changePercent" sortField={sortField} sortDir={sortDir} />
                    </div>
                  </TableHead>
                  <TableHead className="text-right cursor-pointer select-none" onClick={() => handleSort('totalScore')}>
                    <div className="flex items-center gap-1">
                      امتیاز <SortIcon field="totalScore" sortField={sortField} sortDir={sortDir} />
                    </div>
                  </TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {paginated.map(({ data: sym, score }) => (
                  <SymbolHoverCard key={sym.isin} symbol={sym} score={score}>
                    <TableRow
                      className="cursor-pointer"
                      onClick={() => onSymbolClick(sym, score)}
                    >
                      <TableCell className="font-medium text-sm">{sym.symbol}</TableCell>
                      <TableCell className="text-xs text-muted-foreground hidden md:table-cell max-w-[200px] truncate">
                        {sym.name}
                      </TableCell>
                      <TableCell className="hidden sm:table-cell">
                        <Badge variant="outline" className="text-xs">
                          {sym.market}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-sm font-medium">
                        {formatPrice(sym.price)}
                      </TableCell>
                      <TableCell>
                        <span className={`text-sm font-medium flex items-center gap-0.5 ${
                          sym.changePercent >= 0 ? 'text-chart-4' : 'text-destructive'
                        }`}>
                          {sym.changePercent >= 0 ? '▲' : '▼'}
                          {Math.abs(sym.changePercent).toFixed(2)}%
                        </span>
                      </TableCell>
                      <TableCell>
                        <span className={`text-sm font-bold ${getScoreColor(score.totalScore)}`}>
                          {score.totalScore}
                        </span>
                      </TableCell>
                    </TableRow>
                  </SymbolHoverCard>
                ))}
              </TableBody>
            </Table>
          </div>
        </CardContent>
      </Card>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-center gap-2">
          <button
            className="px-3 py-1.5 text-sm rounded-md border hover:bg-accent disabled:opacity-50 duration-300 ease-magic"
            onClick={() => setPage(p => Math.max(1, p - 1))}
            disabled={page === 1}
          >
            قبلی
          </button>
          <span className="text-sm text-muted-foreground">
            صفحه {new Intl.NumberFormat('fa-IR').format(page)} از {new Intl.NumberFormat('fa-IR').format(totalPages)}
          </span>
          <button
            className="px-3 py-1.5 text-sm rounded-md border hover:bg-accent disabled:opacity-50 duration-300 ease-magic"
            onClick={() => setPage(p => Math.min(totalPages, p + 1))}
            disabled={page === totalPages}
          >
            بعدی
          </button>
        </div>
      )}
    </div>
  );
}
