'use client';

import { useState } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { ScrollArea } from '@/components/ui/scroll-area';
import { ChevronRight, ChevronDown, Network, Eye, Layers, Database } from 'lucide-react';
import { PROJECT_HIERARCHY, MainDimension, SubDimension, Aspect } from '@/lib/hierarchy';
import { cn } from '@/lib/utils';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';

interface HierarchyExplorerProps {
  open: boolean;
  onClose: () => void;
}

export function HierarchyExplorer({ open, onClose }: HierarchyExplorerProps) {
  const [expandedNodes, setExpandedNodes] = useState<Set<string>>(new Set(['TD-01']));
  const [searchQuery, setSearchQuery] = useState('');

  const toggleNode = (id: string) => {
    const next = new Set(expandedNodes);
    if (next.has(id)) {
      next.delete(id);
    } else {
      next.add(id);
    }
    setExpandedNodes(next);
  };

  const isExpanded = (id: string) => expandedNodes.has(id);

  // Filter logic (simple)
  const filteredHierarchy = searchQuery.trim() === '' 
    ? PROJECT_HIERARCHY 
    : PROJECT_HIERARCHY.map(main => ({
        ...main,
        subDimensions: main.subDimensions.filter(sub => 
          sub.name.includes(searchQuery) || 
          sub.aspects.some(asp => asp.name.includes(searchQuery))
        )
      })).filter(main => main.name.includes(searchQuery) || main.subDimensions.length > 0);

  return (
     <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
       <DialogContent className="max-w-4xl max-h-[90vh] flex flex-col p-0 overflow-hidden card-tarot">
         <DialogHeader className="p-6 pb-2">
           <div className="flex items-center gap-3">
             <div className="p-2 bg-primary/10 rounded-lg">
               <Network className="w-6 h-6 text-primary" />
             </div>
             <div>
               <DialogTitle className="text-2xl font-bold">نقشه راه علمی Bedaan6D</DialogTitle>
               <DialogDescription>
                 کاوش در ۲۲۶۸ گره تحلیلی شامل ۶ بعد، ۳۶ زیربعد، ۲۵۲ جنبه و ۲۲۶۸ زیرمجموعه
               </DialogDescription>
             </div>
           </div>
          
           <div className="relative mt-4">
             <Eye className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground input-icon" />
             <Input 
               placeholder="جستجو در ابعاد، جنبه‌ها و شاخص‌ها..." 
               className="input-natural pl-10"
               value={searchQuery}
               onChange={(e) => setSearchQuery(e.target.value)}
             />
           </div>
        </DialogHeader>

        <div className="flex-1 overflow-hidden flex flex-col p-6 pt-2">
          <div className="flex gap-6 mb-4">
            <Badge variant="secondary" className="px-3 py-1">
              <Layers className="w-3.5 h-3.5 ml-1.5" />
              ۴ سطح سلسله‌مراتبی
            </Badge>
            <Badge variant="secondary" className="px-3 py-1">
              <Database className="w-3.5 h-3.5 ml-1.5" />
              ۲۲۶۸ نقطه داده
            </Badge>
          </div>

          <ScrollArea className="flex-1 pr-4">
            <div className="space-y-2">
              {filteredHierarchy.map((main) => (
                <DimensionNode 
                  key={main.id} 
                  node={main} 
                  isExpanded={isExpanded(main.id)}
                  onToggle={() => toggleNode(main.id)}
                  expandedNodes={expandedNodes}
                  toggleNode={toggleNode}
                />
              ))}
            </div>
          </ScrollArea>
        </div>

        <div className="p-4 bg-muted/30 border-t flex justify-between items-center">
          <p className="text-xs text-muted-foreground">
            تمامی محاسبات بر اساس استانداردهای آکادمیک و منابع مستند شده در بخش مراجع است.
          </p>
          <Button variant="outline" size="sm" onClick={onClose}>بستن</Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

function DimensionNode({ 
   node, 
   isExpanded, 
   onToggle,
   expandedNodes,
   toggleNode
 }: { 
   node: MainDimension, 
   isExpanded: boolean, 
   onToggle: () => void,
   expandedNodes: Set<string>,
   toggleNode: (id: string) => void
 }) {
   return (
     <div className="border rounded-xl overflow-hidden bg-card shadow-sm card-tarot">
       <button 
         onClick={onToggle}
         className={cn(
           "w-full flex items-center justify-between p-4 hover:bg-accent/50 transition-colors duration-300 ease-magic",
           isExpanded && "bg-accent/30 border-b"
         )}
       >
         <div className="flex items-center gap-3">
           {isExpanded ? <ChevronDown className="w-5 h-5 text-primary" /> : <ChevronRight className="w-5 h-5 text-muted-foreground" />}
           <span className="font-bold text-lg">{node.name}</span>
           <Badge variant="outline" className="text-[10px] opacity-70">۶ زیربعد</Badge>
         </div>
         <span className="text-[10px] text-muted-foreground font-mono">{node.id}</span>
       </button>

       {isExpanded && (
         <div className="p-4 space-y-3 bg-muted/10 grid-gutter-24">
           {node.subDimensions.map((sub) => (
             <SubDimensionNode 
               key={sub.id} 
               sub={sub} 
               isExpanded={expandedNodes.has(sub.id)}
               onToggle={() => toggleNode(sub.id)}
               expandedNodes={expandedNodes}
               toggleNode={toggleNode}
             />
           ))}
         </div>
       )}
     </div>
   );
 }

function SubDimensionNode({ 
   sub, 
   isExpanded, 
   onToggle,
   expandedNodes,
   toggleNode
 }: { 
   sub: SubDimension, 
   isExpanded: boolean, 
   onToggle: () => void,
   expandedNodes: Set<string>,
   toggleNode: (id: string) => void
 }) {
   return (
     <div className="border border-primary/10 rounded-lg bg-background/50 card-tarot">
       <button 
         onClick={onToggle}
         className={cn(
           "w-full flex items-center justify-between p-3 hover:bg-accent/40 transition-colors text-right duration-300 ease-magic",
           isExpanded && "border-b"
         )}
       >
         <div className="flex items-center gap-2">
           {isExpanded ? <ChevronDown className="w-4 h-4 text-primary" /> : <ChevronRight className="w-4 h-4 text-muted-foreground" />}
           <span className="font-semibold text-sm">{sub.name}</span>
           <Badge variant="secondary" className="text-[9px] h-4">۷ جنبه</Badge>
         </div>
       </button>

       {isExpanded && (
         <div className="p-3 space-y-2">
           {sub.aspects.map((asp) => (
             <AspectNode 
               key={asp.id} 
               asp={asp} 
               isExpanded={expandedNodes.has(asp.id)}
               onToggle={() => toggleNode(asp.id)}
             />
           ))}
         </div>
       )}
     </div>
   );
 }

function AspectNode({ 
   asp, 
   isExpanded, 
   onToggle 
 }: { 
   asp: Aspect, 
   isExpanded: boolean, 
   onToggle: () => void 
 }) {
   return (
     <div className="border border-dashed rounded-md card-tarot">
       <button 
         onClick={onToggle}
         className={cn(
           "w-full flex items-center justify-between p-2 hover:bg-accent/30 transition-colors text-right text-xs duration-300 ease-magic",
           isExpanded && "bg-muted/30 border-b border-dashed"
         )}
       >
         <div className="flex items-center gap-2">
           {isExpanded ? <ChevronDown className="w-3.5 h-3.5 text-primary" /> : <ChevronRight className="w-3.5 h-3.5 text-muted-foreground" />}
           <span className="font-medium">{asp.name}</span>
           <Badge variant="outline" className="text-[8px] h-3.5">۹ زیرمجموعه</Badge>
         </div>
       </button>

       {isExpanded && (
         <div className="p-2 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-1.5 bg-muted/5">
           {asp.subCategories.map((cat) => (
             <div 
               key={cat.id} 
               className="p-1.5 bg-background border rounded text-[10px] text-muted-foreground flex items-center gap-1.5 group hover:border-primary/30 transition-colors duration-300 ease-magic"
             >
               <div className="w-1 h-1 rounded-full bg-primary/30 group-hover:bg-primary transition-colors duration-300 ease-magic" />
               {cat.name}
             </div>
           ))}
         </div>
       )}
     </div>
   );
 }
