'use client';

import { useState } from 'react';
import { ALL_DIMENSION_REFERENCES } from '@/lib/references';
import { toPersianNum } from '@/lib/persian';
import {
  Activity,
  BarChart3,
  Brain,
  Shield,
  Globe,
  Eye,
  BookOpen,
  ChevronDown,
  ChevronUp,
  Calculator,
  ExternalLink,
  X,
} from 'lucide-react';

const DIM_ICONS = [Activity, BarChart3, Brain, Shield, Globe, Eye];

interface ReferencesModalProps {
  open: boolean;
  onClose: () => void;
}

export function ReferencesModal({ open, onClose }: ReferencesModalProps) {
  const [expandedDim, setExpandedDim] = useState<string | null>(null);
  const [expandedRef, setExpandedRef] = useState<string | null>(null);
  const modalTitleId = 'references-modal-title';

  if (!open) return null;

  const totalRefs = ALL_DIMENSION_REFERENCES.reduce((s, d) => s + d.references.length, 0);

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div
        data-testid="references-backdrop"
        className="absolute inset-0 bg-black/70 backdrop-blur-sm"
        onClick={onClose}
      />

      {/* Modal */}
      <div
        role="dialog"
        aria-modal="true"
        aria-labelledby={modalTitleId}
        className="relative w-full max-w-4xl max-h-[90vh] rounded-2xl border overflow-hidden flex flex-col bg-background border-border"
      >
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-border">
          <div className="flex items-center gap-3">
            <div className="size-10 rounded-xl flex items-center justify-center bg-primary/10">
              <BookOpen className="size-5 text-primary" />
            </div>
            <div>
              <h2 id={modalTitleId} className="text-lg font-bold text-foreground">مراجع علمی و معیارهای قابل محاسبه</h2>
              <p className="text-xs text-muted-foreground">
                {toPersianNum(totalRefs)} مرجع علمی در {toPersianNum(6)} بعد تحلیلی
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            data-testid="references-close-top"
            className="size-9 rounded-lg flex items-center justify-center text-muted-foreground hover:text-foreground hover:bg-card transition-colors duration-300"
            title="بستن"
                  aria-label="بستن"
          >
            <X className="size-5" />
          </button>
        </div>

        {/* Body — scrollable */}
        <div className="flex-1 overflow-y-auto px-6 py-4 space-y-3 scrollbar-thin scrollbar-thumb-border scrollbar-track-transparent">
          {ALL_DIMENSION_REFERENCES.map((dim, dimIdx) => {
            const Icon = DIM_ICONS[dimIdx];
            const isExpanded = expandedDim === dim.key;

            return (
              <div
                key={dim.key}
                className={`rounded-xl border overflow-hidden transition-all duration-300 ${isExpanded ? `border-primary` : 'border-border'} bg-card`}
              >
                {/* Dimension header */}
                <button
                  className="w-full flex items-center justify-between px-5 py-3.5 text-right duration-300"
                  onClick={() => setExpandedDim(isExpanded ? null : dim.key)}
                  title={isExpanded ? `بستن ${dim.name}` : `باز کردن ${dim.name}`}
                  aria-label={isExpanded ? `بستن ${dim.name}` : `باز کردن ${dim.name}`}
                >
                  <div className="flex items-center gap-3">
                    <div className={`size-9 rounded-lg flex items-center justify-center bg-primary/10`}>
                      <Icon className={`size-4.5 text-primary`} />
                    </div>
                    <div>
                      <span className="text-sm font-bold text-foreground">{dim.name}</span>
                      <span className="text-xs text-muted-foreground mr-2">{dim.nameEn}</span>
                    </div>
                    <span
                      className={`text-[10px] font-bold px-2 py-0.5 rounded-full bg-primary/10 text-primary`}
                    >
                      {toPersianNum(dim.references.length)} مرجع
                    </span>
                  </div>
                  {isExpanded ? (
                    <ChevronUp className="size-4 text-muted-foreground" />
                  ) : (
                    <ChevronDown className="size-4 text-muted-foreground" />
                  )}
                </button>

                {/* References list */}
                {isExpanded && (
                  <div className="px-5 pb-4 space-y-2">
                    {dim.references.map((ref) => {
                      const isRefExpanded = expandedRef === ref.id;
                      return (
                        <div
                          key={ref.id}
                          className={`rounded-lg border overflow-hidden transition-all duration-200 ${isRefExpanded ? 'border-primary' : 'border-border'} ${isRefExpanded ? 'bg-muted/20' : 'bg-background'}`}
                        >
                          {/* Reference header */}
                          <button
                            className="w-full px-4 py-3 text-right flex items-start justify-between gap-3"
                            onClick={() => setExpandedRef(isRefExpanded ? null : ref.id)}
                            title={isRefExpanded ? `بستن ${ref.metric}` : `باز کردن ${ref.metric}`}
                  aria-label={isRefExpanded ? `بستن ${ref.metric}` : `باز کردن ${ref.metric}`}
                          >
                            <div className="flex-1 min-w-0">
                              <div className="flex items-center gap-2 mb-1">
                                <span
                                  className={`text-[10px] font-mono font-bold px-1.5 py-0.5 rounded bg-primary/10 text-primary`}
                                >
                                  {ref.id}
                                </span>
                                <span className="text-xs font-bold text-foreground truncate">{ref.metric}</span>
                              </div>
                              <p className="text-[11px] text-muted-foreground truncate">
                                {ref.authors} ({ref.year}) — {ref.source}
                              </p>
                            </div>
                            <div className="shrink-0 mt-1">
                              {isRefExpanded ? (
                                <ChevronUp className="size-3.5 text-muted-foreground" />
                              ) : (
                                <ChevronDown className="size-3.5 text-muted-foreground" />
                              )}
                            </div>
                          </button>

                          {/* Expanded detail */}
                          {isRefExpanded && (
                            <div className="px-4 pb-4 space-y-3">
                              {/* Title */}
                              <div>
                                <p className="text-[10px] text-muted-foreground mb-0.5">عنوان مرجع</p>
                                <p className="text-xs font-semibold text-foreground">{ref.title}</p>
                              </div>

                              {/* Metric name */}
                              <div className="flex gap-6">
                                <div>
                                  <p className="text-[10px] text-muted-foreground mb-0.5">معیار قابل محاسبه</p>
                                  <p className={`text-xs font-bold text-primary`}>{ref.metric}</p>
                                </div>
                                <div>
                                  <p className="text-[10px] text-muted-foreground mb-0.5">English Name</p>
                                  <p className="text-xs text-muted-foreground">{ref.metricEn}</p>
                                </div>
                              </div>

                              {/* Formula */}
                              <div
                                className="rounded-lg px-3 py-2.5 border bg-muted/20 border-border"
                              >
                                <div className="flex items-center gap-1.5 mb-1.5">
                                  <Calculator className={`size-3 text-primary`} />
                                  <span className={`text-[10px] font-bold text-primary`}>فرمول محاسبه</span>
                                </div>
                                <p className="text-[11px] font-mono text-foreground leading-relaxed" dir="ltr">
                                  {ref.formula}
                                </p>
                              </div>

                              {/* Description */}
                              <div>
                                <p className="text-[10px] text-muted-foreground mb-0.5">توضیح</p>
                                <p className="text-xs text-muted-foreground leading-relaxed">{ref.description}</p>
                              </div>

                              {/* Source */}
                              <div className="flex items-center gap-1.5 pt-1 border-t border-border">
                                <ExternalLink className="size-3 text-muted-foreground" />
                                <p className="text-[10px] text-muted-foreground">
                                  {ref.authors} ({toPersianNum(ref.year)}) — <span className="italic">{ref.source}</span>
                                </p>
                              </div>
                            </div>
                          )}
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            );
          })}
        </div>

        {/* Footer */}
        <div className="px-6 py-3 border-t flex items-center justify-between border-border">
          <p className="text-[11px] text-muted-foreground">
            مجموع: <span className="font-bold text-foreground">{toPersianNum(totalRefs)}</span> مرجع علمی قابل محاسبه
          </p>
          <button
            onClick={onClose}
            data-testid="references-close-bottom"
            className="px-5 py-2 rounded-lg text-sm font-bold transition-colors duration-300 bg-primary text-primary-foreground hover:bg-primary/90"
          >
            بستن
          </button>
        </div>
      </div>
    </div>
  );
}
