'use client';

import type { SubMetric } from '@/lib/scoring';
import { toPersianNum } from '@/lib/persian';

interface DimensionSpiderChartProps {
  subMetrics: SubMetric[];
  dimensionColor: string;
  size?: number;
}

/* ── Color per dimension key ── */
const DIM_COLORS: Record<string, string> = {
  technical: 'var(--chart-5)',   // was cyan
  fundamental: 'var(--chart-4)', // was emerald
  sentiment: 'var(--chart-1)',   // was violet
  risk: 'var(--chart-3)',        // was amber
  macro: 'var(--chart-2)',       // was rose
  board: 'var(--secondary)',     // was sky
};

export function DimensionSpiderChart({
  subMetrics,
  dimensionColor,
  size = 220,
}: DimensionSpiderChartProps) {
  const n = subMetrics.length;
  if (n < 3) return null;

  const center = size / 2;
  // For more axes (5-6+), use smaller radius to leave room for labels
  const maxRadius = n >= 5 ? size * 0.26 : size * 0.3;
  const labelRadius = maxRadius + (n >= 5 ? 28 : 22);

  const color = dimensionColor;

  // Generate polygon points for a given radius
  const getPoints = (radius: number) => {
    return subMetrics.map((_, i) => {
      const angle = (Math.PI * 2 * i) / n - Math.PI / 2;
      return {
        x: center + radius * Math.cos(angle),
        y: center + radius * Math.sin(angle),
      };
    });
  };

  // Grid rings at 25%, 50%, 75%, 100%
  const gridRings = [0.25, 0.5, 0.75, 1.0].map(r => {
    const pts = getPoints(maxRadius * r);
    return pts.map(p => `${p.x},${p.y}`).join(' ');
  });

  // Data polygon
  const dataPoints = subMetrics.map((metric, i) => {
    const angle = (Math.PI * 2 * i) / n - Math.PI / 2;
    const r = (metric.score / 100) * maxRadius;
    return {
      x: center + r * Math.cos(angle),
      y: center + r * Math.sin(angle),
      angle,
    };
  });
  const dataPolygon = dataPoints.map(p => `${p.x},${p.y}`).join(' ');

  // Axis lines
  const axisPoints = getPoints(maxRadius);

  // Label positions
  const labelPositions = subMetrics.map((metric, i) => {
    const angle = (Math.PI * 2 * i) / n - Math.PI / 2;
    const lx = center + labelRadius * Math.cos(angle);
    const ly = center + labelRadius * Math.sin(angle);
    return { x: lx, y: ly, name: metric.name, score: metric.score };
  });

  return (
    <svg
      width={size}
      height={size}
      viewBox={`0 0 ${size} ${size}`}
      className="select-none direction-ltr"
    >
      {/* Grid rings */}
      {gridRings.map((pts, i) => (
        <polygon
          key={`ring-${i}`}
          points={pts}
          fill="none"
          stroke="currentColor"
          strokeOpacity={0.08}
          strokeWidth="1"
        />
      ))}

      {/* Axis lines */}
      {axisPoints.map((pt, i) => (
        <line
          key={`axis-${i}`}
          x1={center}
          y1={center}
          x2={pt.x}
          y2={pt.y}
          stroke="currentColor"
          strokeOpacity={0.08}
          strokeWidth="1"
        />
      ))}

      {/* Filled data area */}
      <polygon
        points={dataPolygon}
        fill={`${color}20`}
        stroke={`${color}99`}
        strokeWidth="2"
        strokeLinejoin="round"
      />

      {/* Data points */}
      {dataPoints.map((pt, i) => (
        <g key={`dot-${i}`}>
          <circle cx={pt.x} cy={pt.y} r="5" fill={color} fillOpacity={0.3} />
          <circle cx={pt.x} cy={pt.y} r="3" fill={color} />
        </g>
      ))}

      {/* Labels */}
      {labelPositions.map((lp, i) => {
        let textAnchor: "start" | "end" | "middle" = 'middle';
        let dx = 0;
        if (lp.x > center + 5) { textAnchor = 'start'; dx = 4; }
        else if (lp.x < center - 5) { textAnchor = 'end'; dx = -4; }

        return (
          <g key={`label-${i}`}>
            <text
              x={lp.x + dx}
              y={lp.y - 6}
              textAnchor={textAnchor}
              className="fill-foreground"
              fontSize="9"
              fontWeight="600"
              fontFamily="inherit"
            >
              {lp.name}
            </text>
            <text
              x={lp.x + dx}
              y={lp.y + 7}
              textAnchor={textAnchor}
              fill={color}
              fontSize="10"
              fontWeight="800"
              fontFamily="inherit"
            >
              {toPersianNum(lp.score)}
            </text>
          </g>
        );
      })}
    </svg>
  );
}

export { DIM_COLORS };
