'use client';

import { useEffect, useState, useMemo } from 'react';
import { Badge } from '@/components/ui/badge';
import { Skeleton } from '@/components/ui/skeleton';
import { ProgressDynamic } from '@/components/ui/progress-dynamic';
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from '@/components/ui/accordion';
import { Button } from '@/components/ui/button';
import { SymbolData, computeSymbolScore, getScoreColor, getScoreBgLight, getProgressColor, SymbolScore } from '@/lib/scoring';
import { adaptSymbolItems, type BRSSymbolItem } from '@/lib/data-adapter';
import { MOCK_SYMBOLS, groupBySector } from '@/lib/mock-data';
import { Building2, ExternalLink } from 'lucide-react';
import { SymbolHoverCard } from '@/components/SymbolHoverCard';
import { IndustryDetail } from './IndustryDetail';

interface IndustriesTabProps {
  onSymbolClick: (symbol: SymbolData, score: SymbolScore) => void;
}

interface IndustryData {
  name: string;
  symbols: SymbolData[];
  avgScore: number;
  symbolCount: number;
  avgChange: number;
}

export function IndustriesTab({ onSymbolClick }: IndustriesTabProps) {
  const [symbols, setSymbols] = useState<SymbolData[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedIndustry, setSelectedIndustry] = useState<string | null>(null);

  useEffect(() => {
    async function fetchData() {
      try {
        const res = await fetch('/api/market');
        if (res.ok) {
          const data = await res.json();
          const rawSymbols = data?.data?.symbols || data?.symbols || [];
          if (rawSymbols.length > 0) {
            const adapted = adaptSymbolItems(rawSymbols as BRSSymbolItem[]);
            if (adapted.length > 0) {
              setSymbols(adapted);
              setLoading(false);
              return;
            }
          }
        }
      } catch {
        // fallback
      }
      setSymbols(MOCK_SYMBOLS);
      setLoading(false);
    }
    fetchData();
  }, []);

  const industries = useMemo((): IndustryData[] => {
    const grouped = groupBySector(symbols);
    return Object.entries(grouped)
      .map(([name, syms]) => {
        const scores = syms.map(s => computeSymbolScore(s));
        const avgScore = Math.round(scores.reduce((sum, s) => sum + s.totalScore, 0) / scores.length);
        const avgChange = syms.reduce((sum, s) => sum + s.changePercent, 0) / syms.length;
        return {
          name,
          symbols: syms,
          avgScore,
          symbolCount: syms.length,
          avgChange: Math.round(avgChange * 100) / 100,
        };
      })
      .sort((a, b) => b.avgScore - a.avgScore);
  }, [symbols]);

  if (loading) {
    return (
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {Array.from({ length: 10 }).map((_, i) => (
          <Skeleton key={i} className="h-32 rounded-xl card-tarot" />
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-lg font-semibold flex items-center gap-2">
          <Building2 className="size-5 text-primary" />
          صنایع بازار
        </h2>
        <Badge variant="secondary">
          {industries.length} صنعت
        </Badge>
      </div>

      <Accordion type="multiple" className="space-y-2">
        {industries.map((industry, idx) => (
          <AccordionItem
            key={industry.name}
            value={`industry-${idx}`}
            className="border rounded-lg px-4"
          >
            <AccordionTrigger className="hover:no-underline py-3">
              <div className="flex items-center justify-between w-full gap-4">
                <div className="flex items-center gap-3 flex-1 min-w-0">
                  <div className="flex flex-col items-center min-w-[4rem]">
                    <span className={`text-2xl font-bold ${getScoreColor(industry.avgScore)}`}>
                      {industry.avgScore}
                    </span>
                    <span className="text-xs text-muted-foreground">از 100</span>
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                      <span className="font-semibold text-sm">{industry.name}</span>
                      <Badge variant="secondary" className="text-xs">
                        {industry.symbolCount} نماد
                      </Badge>
                      <span className={`text-xs font-medium flex items-center gap-0.5 ${
                        industry.avgChange >= 0 ? 'text-chart-4' : 'text-destructive'
                      }`}>
                        {industry.avgChange >= 0 ? '▲' : '▼'}
                        {Math.abs(industry.avgChange).toFixed(2)}%
                      </span>
                    </div>
                    <ProgressDynamic 
                      value={industry.avgScore} 
                      className="h-2 w-full rounded-full bg-muted overflow-hidden"
                      barClassName={getProgressColor(industry.avgScore)}
                    />
                  </div>
                </div>
                <Button
                  variant="ghost"
                  size="sm"
                  className="flex-shrink-0"
                  onClick={(e) => {
                    e.stopPropagation();
                    setSelectedIndustry(industry.name);
                  }}
                >
                  <ExternalLink className="size-4" />
                </Button>
              </div>
            </AccordionTrigger>
            <AccordionContent>
              <div className={`rounded-lg border p-3 ${getScoreBgLight(industry.avgScore)}`}>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2 max-h-64 overflow-y-auto">
                  {industry.symbols
                    .sort((a, b) => {
                      const sa = computeSymbolScore(a);
                      const sb = computeSymbolScore(b);
                      return sb.totalScore - sa.totalScore;
                    })
                    .map(sym => {
                      const score = computeSymbolScore(sym);
                      return (
                        <SymbolHoverCard key={sym.isin} symbol={sym} score={score}>
                          <button
                            className="flex items-center justify-between p-2 rounded-md bg-background/50 hover:bg-background transition-colors text-right w-full duration-300 ease-magic"
                            onClick={() => onSymbolClick(sym, score)}
                          >
                            <div className="flex flex-col items-start">
                              <span className="text-sm font-medium">{sym.symbol}</span>
                              <span className="text-xs text-muted-foreground">{sym.name}</span>
                            </div>
                            <div className="flex flex-col items-end gap-0.5">
                              <span className={`text-sm font-bold ${getScoreColor(score.totalScore)}`}>
                                {score.totalScore}
                              </span>
                              <span className={`text-xs ${
                                sym.changePercent >= 0 ? 'text-chart-4' : 'text-destructive'
                              }`}>
                                {sym.changePercent >= 0 ? '▲' : '▼'}
                                {Math.abs(sym.changePercent).toFixed(1)}%
                              </span>
                            </div>
                          </button>
                        </SymbolHoverCard>
                      );
                    })}
                </div>
              </div>
            </AccordionContent>
          </AccordionItem>
        ))}
      </Accordion>

      {/* Industry Detail Modal */}
      <IndustryDetail
        industryName={selectedIndustry || ''}
        symbols={symbols}
        open={selectedIndustry !== null}
        onClose={() => setSelectedIndustry(null)}
      />
    </div>
  );
}