'use client';

import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/components/ui/accordion';
import { HoverCard, HoverCardTrigger, HoverCardContent } from '@/components/ui/hover-card';
import { Badge } from '@/components/ui/badge';
import { ProgressDynamic } from '@/components/ui/progress-dynamic';
import { DimensionSpiderChart, DIM_COLORS } from '@/components/DimensionSpiderChart';
import { DimensionScore, getScoreColor, getScoreBgLight, getProgressColor } from '@/lib/scoring';
import { toPersianNum } from '@/lib/persian';

interface DimensionCardProps {
  dimension: DimensionScore;
  index: number;
}

export function DimensionCard({ dimension, index }: DimensionCardProps) {
  const dimColor = DIM_COLORS[dimension.key] || '#06b6d4';

  return (
    <Accordion type="single" collapsible className="w-full">
      <AccordionItem value={`dim-${index}`} className="border rounded-lg px-4">
        <HoverCard openDelay={400} closeDelay={200}>
          <HoverCardTrigger asChild>
            <AccordionTrigger className="hover:no-underline py-4">
              <div className="flex items-center justify-between w-full gap-4">
                <div className="flex items-center gap-3 flex-1 min-w-0">
                  <div className="flex flex-col items-center">
                    <span className={`text-2xl font-bold ${dimension.color}`}>
                      {dimension.score}
                    </span>
                    <span className="text-xs text-muted-foreground">
                      \u0627\u0632 \u06f1\u06f0\u06f0
                    </span>
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                      <span
                        className={`size-2.5 rounded-full shrink-0 bg-[${dimColor}]`}
                      />
                      <span className="font-semibold text-sm">{dimension.name}</span>
                      <Badge variant="secondary" className="text-xs">
                        \u0648\u0632\u0646: {(dimension.weight * 100).toFixed(0)}%
                      </Badge>
                    </div>
                    <ProgressDynamic 
                      value={dimension.percentage} 
                      className="h-3 w-full rounded-full bg-muted overflow-hidden"
                      barClassName={getProgressColor(dimension.score)}
                    />
                  </div>
                </div>
              </div>
            </AccordionTrigger>
          </HoverCardTrigger>
          <HoverCardContent
            side="bottom"
            align="center"
            className="w-auto p-3 z-50"
            sideOffset={8}
            collisionPadding={16}
          >
            <div className="flex flex-col items-center gap-2">
                {/* Header */}
                <div className="flex items-center gap-2 w-full">
                  <span
                    className={`size-3 rounded-full shrink-0 ${dimColor}`}
                  />
                  <span className="font-bold text-sm">{dimension.name}</span>
                  <span className={`font-black text-lg mr-auto ${dimension.color}`}>
                  {toPersianNum(dimension.score)}
                </span>
                <span className="text-xs text-muted-foreground">\u0627\u0632 \u06f1\u06f0\u06f0</span>
              </div>
              {/* Spider chart for sub-metrics */}
              <DimensionSpiderChart
                subMetrics={dimension.subMetrics}
                dimensionColor={dimColor}
                size={220}
              />
            </div>
          </HoverCardContent>
        </HoverCard>
        <AccordionContent>
          <div className={`rounded-lg border p-4 ${getScoreBgLight(dimension.score)}`}>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              {dimension.subMetrics.map((metric, i) => (
                <div key={i} className="flex flex-col gap-1 p-2 rounded-md bg-background/50">
                  <div className="flex items-center justify-between">
                    <span className="text-sm font-medium">{metric.name}</span>
                    <span className={`text-sm font-bold ${getScoreColor(metric.score)}`}>
                      {metric.score}
                    </span>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-xs text-muted-foreground">{metric.description}</span>
                    <span className="text-xs font-medium">{metric.value}</span>
                  </div>
                  <ProgressDynamic 
                    value={metric.score} 
                    className="h-1.5 w-full rounded-full bg-muted overflow-hidden mt-1"
                    barClassName={getProgressColor(metric.score)}
                  />
                </div>
              ))}
            </div>
          </div>
        </AccordionContent>
      </AccordionItem>
    </Accordion>
  );
}
