'use client';

import { useEffect, useState, lazy, Suspense } from 'react';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { DashboardTab } from '@/components/DashboardTab';
import { IndustriesTab } from '@/components/IndustriesTab';
import { CompaniesTab } from '@/components/CompaniesTab';
import { LiveClock } from '@/components/LiveClock';
import { PriceTickerBar } from '@/components/PriceTickerBar';
import { ScoreTickerBar } from '@/components/ScoreTickerBar';
import { NewsTickerBar } from '@/components/NewsTickerBar';
import { ElegantBackground } from '@/components/ElegantBackground';
import { LandingPage } from '@/components/LandingPage';
import { SymbolData, SymbolScore } from '@/lib/scoring';
import { BarChart3, Building2, LayoutDashboard, TrendingUp, BookOpen } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { ReferencesModal } from '@/components/ReferencesModal';
import { DownloadProjectButton } from '@/components/DownloadProjectButton';

// Lazy load SymbolDetail for better performance
const SymbolDetail = lazy(() => import('@/components/SymbolDetail'));

export default function Home() {
  const [selectedSymbol, setSelectedSymbol] = useState<SymbolData | null>(null);
  const [selectedScore, setSelectedScore] = useState<SymbolScore | null>(null);
  const [detailOpen, setDetailOpen] = useState(false);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [view, setView] = useState<'landing' | 'dashboard'>('landing');
  const [refsOpen, setRefsOpen] = useState(false);

  const handleSymbolClick = (symbol: SymbolData, score: SymbolScore) => {
    setSelectedSymbol(symbol);
    setSelectedScore(score);
    setDetailOpen(true);
  };

  const handleEnterDashboard = () => {
    setView('dashboard');
  };

  const handleBackToLanding = () => {
    setView('landing');
  };

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    if (params.get('view') === 'dashboard') {
      const timer = setTimeout(() => {
        setView('dashboard');
      }, 0);
      
      return () => clearTimeout(timer);
    }
  }, []);



  // Landing Page View
  if (view === 'landing') {
    return (
      <>
        <LandingPage onEnterDashboard={handleEnterDashboard} onOpenReferences={() => setRefsOpen(true)} />
        <ReferencesModal open={refsOpen} onClose={() => setRefsOpen(false)} />
      </>
    );
  }

  // Dashboard View
  return (
    <div className="min-h-screen flex flex-col bg-background text-foreground relative">
      {/* Subtle Background */}
      <ElegantBackground />

      {/* Header */}
      <header className="border-b border-border bg-background/90 backdrop-blur-xl sticky top-0 z-40">
        <div className="container mx-auto px-4 py-3">
          <div className="flex items-center justify-between">
            <div
              className="flex items-center gap-3 cursor-pointer group"
              onClick={handleBackToLanding}
              title="بازگشت به صفحه اصلی"
            >
              <div className="size-10 rounded-xl bg-primary flex items-center justify-center shadow-lg shadow-primary/10 group-hover:shadow-primary/25 transition-shadow duration-300">
                <TrendingUp className="size-5 text-primary-foreground" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-foreground tracking-wide group-hover:text-primary transition-colors duration-200">Bedaan6D</h1>
                <p className="text-[10px] text-muted-foreground">تحلیل هوشمند بازار بورس تهران</p>
              </div>
            </div>
            <div className="flex items-center gap-3">
              <LiveClock />
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setRefsOpen(true)}
                className="text-muted-foreground hover:text-primary hover:bg-card gap-1.5 text-xs"
              >
                <BookOpen className="size-4" />
                <span className="hidden sm:inline">مراجع علمی</span>
              </Button>
              <DownloadProjectButton variant="outline" />
            </div>
          </div>
        </div>
      </header>

      {/* Ticker Bars */}
      <div className="sticky top-[57px] z-30">
        <PriceTickerBar />
        <ScoreTickerBar />
        <NewsTickerBar />
      </div>

      {/* Main Content */}
      <main className="flex-1 container mx-auto px-4 py-6 relative z-10">
        <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
          <TabsList className="w-full sm:w-fit mb-6 bg-card border border-border">
            <TabsTrigger value="dashboard" className="gap-1.5 text-sm data-[state=active]:bg-background data-[state=active]:text-primary data-[state=active]:shadow-sm text-muted-foreground">
              <LayoutDashboard className="size-4" />
              داشبورد
            </TabsTrigger>
            <TabsTrigger value="industries" className="gap-1.5 text-sm data-[state=active]:bg-background data-[state=active]:text-primary data-[state=active]:shadow-sm text-muted-foreground">
              <Building2 className="size-4" />
              صنایع
            </TabsTrigger>
            <TabsTrigger value="companies" className="gap-1.5 text-sm data-[state=active]:bg-background data-[state=active]:text-primary data-[state=active]:shadow-sm text-muted-foreground">
              <BarChart3 className="size-4" />
              شرکت‌ها
            </TabsTrigger>
          </TabsList>

          <TabsContent value="dashboard">
            <DashboardTab onSymbolClick={handleSymbolClick} />
          </TabsContent>

          <TabsContent value="industries">
            <IndustriesTab onSymbolClick={handleSymbolClick} />
          </TabsContent>

          <TabsContent value="companies">
            <CompaniesTab onSymbolClick={handleSymbolClick} />
          </TabsContent>
        </Tabs>
      </main>

      {/* Footer */}
      <footer className="mt-auto border-t border-border py-4 bg-background">
        <div className="container mx-auto px-4">
          <div className="flex flex-col sm:flex-row items-center justify-between gap-2 text-xs text-muted-foreground">
            <div className="flex items-center gap-2">
              <span>© ۱۴۰۵ Bedaan6D</span>
              <span className="hidden sm:inline">|</span>
              <span className="hidden sm:inline">تحلیل هوشمند بازار بورس تهران</span>
            </div>
            <div className="flex items-center gap-2">
              <span>منبع داده:</span>
              <span className="font-medium text-primary/60">BRS API</span>
            </div>
          </div>
        </div>
      </footer>

      {/* References Modal */}
      <ReferencesModal open={refsOpen} onClose={() => setRefsOpen(false)} />

      {/* Symbol Detail Dialog - Lazy loaded with Suspense */}
      <Suspense fallback={null}>
        <SymbolDetail
          symbol={selectedSymbol}
          score={selectedScore}
          open={detailOpen}
          onClose={() => setDetailOpen(false)}
        />
      </Suspense>
    </div>
  );
}
