'use client';

import { useEffect, useState } from 'react';
import { MOCK_NEWS } from '@/lib/mock-data';
import { Newspaper } from 'lucide-react';

interface NewsItem {
  title: string;
  source: string;
  time: string;
  url: string;
}

export function NewsTickerBar() {
  const [news, setNews] = useState<NewsItem[]>(MOCK_NEWS);

  useEffect(() => {
    let cancelled = false;
    async function fetchNews() {
      try {
        const res = await fetch('/api/news');
        if (!res.ok) return;
        const data = await res.json();
        const raw = data?.data || [];
        if (!cancelled && Array.isArray(raw) && raw.length > 0) {
          const adapted = raw.slice(0, 10).map((n: { title?: string; source?: string; date?: string; url?: string }) => ({
            title: n.title || '', source: n.source || '', time: n.date || '', url: n.url || '#',
          }));
          setNews(adapted);
        }
      } catch { /* use mock */ }
    }
    fetchNews();
    return () => { cancelled = true; };
  }, []);

  const tickerItems = [...news, ...news];

  return (
    <div className="border-b border-border py-1.5 bg-muted/30">
      <div className="container mx-auto px-4">
        <div className="flex items-center gap-2">
          <div className="flex items-center gap-1 shrink-0 text-xs font-semibold text-primary">
            <Newspaper className="size-3.5" />
            <span>اخبار</span>
          </div>
          <div className="overflow-hidden flex-1">
            <div className="flex gap-8 animate-ticker-scroll-slow whitespace-nowrap" style={{ width: 'max-content' }}>
              {tickerItems.map((item, i) => (
                <a
                  key={i}
                  href={item.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="inline-flex items-center gap-2 text-xs text-muted-foreground hover:text-primary transition-colors duration-300"
                  style={{ transitionTimingFunction: 'cubic-bezier(0.25, 0.1, 0.25, 1.0)' }}
                >
                  <span className="font-medium">{item.title}</span>
                  <span className="text-border">— {item.source}</span>
                </a>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
