'use client';

import { useEffect, useRef, useState } from 'react';
import { MOCK_INDICES, MOCK_GOLD_CURRENCY, MOCK_SYMBOLS } from '@/lib/mock-data';
import { toPersianNum, formatPersianPrice } from '@/lib/persian';
import { TrendingUp } from 'lucide-react';

interface TickerItem {
  name: string;
  value: string;
  change: number;
  changePercent: number;
}

function buildItems(): TickerItem[] {
  const items: TickerItem[] = [];
  MOCK_INDICES.forEach(idx => {
    items.push({ name: idx.name, value: formatPersianPrice(idx.value), change: idx.change, changePercent: idx.changePercent });
  });
  MOCK_GOLD_CURRENCY.forEach(gc => {
    items.push({ name: gc.name, value: formatPersianPrice(gc.price), change: gc.change, changePercent: gc.changePercent });
  });
  const topSymbols = [...MOCK_SYMBOLS]
    .sort((a, b) => Math.abs(b.changePercent) - Math.abs(a.changePercent))
    .slice(0, 15);
  topSymbols.forEach(s => {
    items.push({ name: s.symbol, value: formatPersianPrice(s.price), change: s.change, changePercent: s.changePercent });
  });
  return items;
}

const ITEMS = buildItems();

export function PriceTickerBar() {
  const scrollRef = useRef<HTMLDivElement>(null);
  const [apiItems, setApiItems] = useState<TickerItem[]>([]);

  useEffect(() => {
    let cancelled = false;
    async function fetchIndices() {
      try {
        const res = await fetch('/api/indices');
        if (!res.ok) return;
        const data = await res.json();
        const raw = data?.data || data?.indices || [];
        if (!cancelled && Array.isArray(raw) && raw.length > 0) {
          const fetched: TickerItem[] = raw.map((idx: { name?: string; value?: number; change?: number; changePercent?: number }) => ({
            name: idx.name || '', value: formatPersianPrice(idx.value || 0), change: idx.change || 0, changePercent: idx.changePercent || 0,
          }));
          setApiItems(fetched);
        }
      } catch { /* use mock */ }
    }
    fetchIndices();
    return () => { cancelled = true; };
  }, []);

  const displayItems = apiItems.length > 0 ? [...apiItems, ...ITEMS.slice(apiItems.length)] : ITEMS;
  const tickerItems = [...displayItems, ...displayItems];

  return (
    <div className="border-b border-border py-1.5 bg-muted/30 backdrop-blur-sm">
      <div className="container mx-auto px-4">
        <div className="flex items-center gap-2">
          <div className="flex items-center gap-1 shrink-0 text-xs font-semibold text-primary">
            <TrendingUp className="size-3.5" />
            <span>قیمت</span>
          </div>
          <div className="overflow-hidden flex-1">
            <div ref={scrollRef} className="flex gap-6 animate-ticker-scroll whitespace-nowrap" style={{ width: 'max-content' }}>
              {tickerItems.map((item, i) => (
                <span key={i} className="inline-flex items-center gap-1.5 text-xs">
                  <span className="font-medium text-muted-foreground">{item.name}</span>
                  <span className="font-bold text-foreground">{item.value}</span>
                  <span className={`font-bold ${item.changePercent >= 0 ? 'text-primary' : 'text-destructive'}`}>
                    {item.changePercent >= 0 ? '▲' : '▼'} {toPersianNum(Math.abs(item.changePercent).toFixed(2))}٪
                  </span>
                </span>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
