'use client';

import { useMemo } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
} from 'recharts';
import {
  Building2,
  TrendingUp,
  TrendingDown,
  BarChart3,
  Activity,
  Users,
  Briefcase,
} from 'lucide-react';
import { SymbolData, formatNumber, formatPrice } from '@/lib/scoring';

// --- Constants ---
const INDUSTRY_COLORS = [
  'var(--color-primary)', 
  'var(--color-chart-2)', 
  'var(--color-chart-3)', 
  'var(--color-chart-4)', 
  'var(--color-chart-5)', 
  'var(--color-chart-1)'
];
const EMPTY_ARRAY: SymbolData[] = [];

// --- Types ---
interface IndustryDetailProps {
  industryName: string;
  symbols: SymbolData[];
  open: boolean;
  onClose: () => void;
}

interface IndustryStats {
  count: number;
  avgChange: number;
  topGainers: SymbolData[];
  topLosers: SymbolData[];
  performanceData: Array<{ name: string; change: number; volume: number }>;
  distributionData: Array<{ name: string; value: number }>;
  industrySymbols: SymbolData[];
}

// --- Helper Components (Clean & Reusable) ---
function StatCard({
  icon: Icon,
  label,
  value,
  trend,
}: {
  icon: React.ElementType;
  label: string;
  value: React.ReactNode;
  trend?: number;
}) {
  const isPositive = trend !== undefined && trend >= 0;
  
  return (
    <article className="bg-gradient-to-br from-card to-background rounded-2xl p-6 border border-border">
      <div className="flex items-center gap-2 mb-2 text-xs text-muted-foreground">
        <Icon className="size-4" />
        <span>{label}</span>
      </div>
      <div className={`text-4xl font-black text-foreground flex items-center gap-2 ${
        trend !== undefined ? (isPositive ? 'text-primary' : 'text-destructive') : ''
      }`}>
        {trend !== undefined && (
          isPositive ? <TrendingUp className="size-6" /> : <TrendingDown className="size-6" />
        )}
        {value}
      </div>
    </article>
  );
}

function SymbolList({
  title,
  symbols,
  colorClass,
  Icon,
}: {
  title: string;
  symbols: SymbolData[];
  colorClass: string;
  Icon: React.ElementType;
}) {
  if (symbols.length === 0) return null;

  return (
    <section className="bg-card rounded-2xl p-4 border border-border">
      <h4 className={`text-sm font-semibold mb-3 ${colorClass} flex items-center gap-2`}>
        <Icon className="size-4" />
        {title}
      </h4>
      <div className="space-y-2">
        {symbols.map((symbol) => (
          <div 
            key={symbol.isin} 
            className="flex items-center justify-between p-2 bg-background/5 rounded-lg hover:bg-background/10 transition-colors"
          >
            <span className="font-medium">{symbol.symbol}</span>
            <span className={`font-semibold ${colorClass}`}>
              {symbol.changePercent >= 0 ? '+' : ''}{symbol.changePercent.toFixed(2)}%
            </span>
          </div>
        ))}
      </div>
    </section>
  );
}

// --- Main Component ---
export function IndustryDetail({ industryName, symbols, open, onClose }: IndustryDetailProps) {
  const industryData = useMemo<IndustryStats>(() => {
    const industrySymbols = symbols.filter((s) => s.sector === industryName);
    
    if (industrySymbols.length === 0) {
      return {
        count: 0,
        avgChange: 0,
        topGainers: [] as SymbolData[],
        topLosers: [] as SymbolData[],
        performanceData: [],
        distributionData: [],
        industrySymbols: [] as SymbolData[],
      };
    }

    const avgChange = industrySymbols.reduce((sum, s) => sum + s.changePercent, 0) / industrySymbols.length;

    const performanceData = industrySymbols
      .slice(0, 10)
      .map((s) => ({
        name: s.symbol,
        change: s.changePercent,
        volume: s.volume,
      }));

    const distributionData = [
      { name: 'صعودی', value: industrySymbols.filter((s) => s.changePercent > 0).length },
      { name: 'نزولی', value: industrySymbols.filter((s) => s.changePercent < 0).length },
      { name: 'بدون تغییر', value: industrySymbols.filter((s) => s.changePercent === 0).length },
    ].filter((d) => d.value > 0);

    return {
      count: industrySymbols.length,
      avgChange,
      topGainers: [...industrySymbols].sort((a, b) => b.changePercent - a.changePercent).slice(0, 5),
      topLosers: [...industrySymbols].sort((a, b) => a.changePercent - b.changePercent).slice(0, 5),
      performanceData,
      distributionData,
      industrySymbols,
    };
  }, [industryName, symbols]);

  if (!open) return null;

  return (
    <Dialog open={open} onOpenChange={(isOpen) => !isOpen && onClose()}>
      <DialogContent 
        className="max-w-4xl max-h-[90vh] overflow-y-auto"
        aria-label={`جزئیات صنعت ${industryName}`}
      >
        <DialogHeader>
          <DialogTitle className="text-2xl font-bold flex items-center gap-3">
            <Building2 className="size-8 text-primary" />
            <span>{industryName}</span>
            <Badge variant="secondary" className="text-sm">
              {industryData.count} نماد
            </Badge>
          </DialogTitle>
          <DialogDescription className="text-base text-muted-foreground">
            تحلیل کلی صنعت و عملکرد نمادها
          </DialogDescription>
        </DialogHeader>

        <Tabs defaultValue="overview">
          <TabsList className="w-full sm:w-auto mb-6 bg-card border border-border">
            <TabsTrigger value="overview" className="text-sm">نمای کلی</TabsTrigger>
            <TabsTrigger value="performance" className="text-sm">عملکرد</TabsTrigger>
            <TabsTrigger value="symbols" className="text-sm">نمادها</TabsTrigger>
          </TabsList>

          {/* Overview Tab */}
          <TabsContent value="overview" className="space-y-6">
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              <StatCard 
                icon={Briefcase} 
                label="تعداد نمادها" 
                value={industryData.count} 
              />
              <StatCard 
                icon={Activity} 
                label="میانگین تغییر" 
                value={`${industryData.avgChange.toFixed(2)}%`} 
                trend={industryData.avgChange} 
              />
              <StatCard 
                icon={Users} 
                label="توزیع عملکرد" 
                value={industryData.distributionData.length} 
              />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              {/* Pie Chart Section */}
              <section aria-label="نمودار توزیع عملکرد" className="bg-card rounded-2xl p-6 border border-border">
                <h3 className="text-sm font-semibold mb-4 flex items-center gap-2">
                  <PieChart className="size-4 text-primary" />
                  توزیع عملکرد نمادها
                </h3>
                <ResponsiveContainer width="100%" height={250}>
                  <PieChart>
                    <Pie
                      data={industryData.distributionData}
                      cx="50%"
                      cy="50%"
                      labelLine={false}
                      label={({ name, percent }) => `${name} ${(percent ?? 0) * 100}%`}
                      outerRadius={80}
                      dataKey="value"
                    >
                      {industryData.distributionData.map((entry, index) => (
                        <Cell 
                          key={`cell-${index}-${entry.name}`} 
                          fill={INDUSTRY_COLORS[index % INDUSTRY_COLORS.length]} 
                        />
                      ))}
                    </Pie>
                    <Tooltip 
                      contentStyle={{ 
                        backgroundColor: 'var(--color-card)', 
                        border: '1px solid var(--color-border)',
                        borderRadius: '8px'
                      }}
                      labelStyle={{ color: 'var(--color-muted-foreground)' }}
                    />
                  </PieChart>
                </ResponsiveContainer>
              </section>

              {/* Top Gainers/Losers */}
              <div className="space-y-4">
                <SymbolList 
                  title="بهترین عملکرد" 
                  symbols={industryData.topGainers} 
                  colorClass="text-primary" 
                  Icon={TrendingUp} 
                />
                <SymbolList 
                  title="ضعیف‌ترین عملکرد" 
                  symbols={industryData.topLosers} 
                  colorClass="text-destructive" 
                  Icon={TrendingDown} 
                />
              </div>
            </div>
          </TabsContent>

          {/* Performance Tab */}
          <TabsContent value="performance" className="space-y-4">
            <section aria-label="نمودار عملکرد نمادها" className="bg-card rounded-2xl p-6 border border-border">
              <h3 className="text-sm font-semibold mb-4 flex items-center gap-2">
                <BarChart3 className="size-4 text-primary" />
                عملکرد نمادها (تغییر درصدی)
              </h3>
              <ResponsiveContainer width="100%" height={350}>
                <BarChart data={industryData.performanceData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="var(--color-border)" />
                  <XAxis 
                    dataKey="name" 
                    stroke="var(--color-muted-foreground)" 
                    style={{ fontSize: '11px' }}
                    tick={{ fill: 'var(--color-muted-foreground)' }}
                  />
                  <YAxis 
                    stroke="var(--color-muted-foreground)" 
                    style={{ fontSize: '11px' }}
                    tick={{ fill: 'var(--color-muted-foreground)' }}
                  />
                  <Tooltip 
                    contentStyle={{ 
                      backgroundColor: 'var(--color-card)', 
                      border: '1px solid var(--color-border)',
                      borderRadius: '8px'
                    }}
                    labelStyle={{ color: 'var(--color-muted-foreground)' }}
                  />
                  <Bar 
                    dataKey="change" 
                    fill="var(--color-primary)" 
                    radius={[4, 4, 0, 0]}
                  />
                </BarChart>
              </ResponsiveContainer>
            </section>
          </TabsContent>

          {/* Symbols Tab */}
          <TabsContent value="symbols" className="space-y-4">
            <section aria-label="لیست نمادها" className="bg-card rounded-2xl p-4 border border-border">
              <div className="overflow-x-auto">
                <table className="w-full text-sm" role="grid">
                  <thead>
                    <tr className="text-muted-foreground border-b border-border">
                      <th scope="col" className="text-right py-3 px-4">نماد</th>
                      <th scope="col" className="text-right py-3 px-4">نام</th>
                      <th scope="col" className="text-right py-3 px-4">قیمت</th>
                      <th scope="col" className="text-right py-3 px-4">تغییر</th>
                      <th scope="col" className="text-right py-3 px-4">حجم</th>
                    </tr>
                  </thead>
                  <tbody>
                    {industryData.industrySymbols.map((s) => (
                      <tr 
                        key={s.isin} 
                        className="border-b border-border/50 hover:bg-background/5 transition-colors"
                        role="row"
                      >
                        <td className="py-3 px-4 font-medium" role="gridcell">{s.symbol}</td>
                        <td className="py-3 px-4 text-muted-foreground" role="gridcell">{s.name}</td>
                        <td className="py-3 px-4" role="gridcell">{formatPrice(s.price)}</td>
                        <td className={`py-3 px-4 font-semibold ${
                          s.changePercent >= 0 ? 'text-primary' : 'text-destructive'
                        }`} role="gridcell">
                          {s.changePercent >= 0 ? '+' : ''}{s.changePercent.toFixed(2)}%
                        </td>
                        <td className="py-3 px-4" role="gridcell">{formatNumber(s.volume)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </section>
          </TabsContent>
        </Tabs>
      </DialogContent>
    </Dialog>
  );
}

export default IndustryDetail;
