'use client';

import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';

interface IndexTrendProps {
  indexValue: number;
  indexChangePercent: number;
  eqWeightValue: number;
  eqWeightChangePercent: number;
}

export function IndexTrend({
  indexValue,
  indexChangePercent,
  eqWeightValue,
  eqWeightChangePercent,
}: IndexTrendProps) {
  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 grid-gutter-24">
      <Card className="card-tarot">
        <CardHeader>
          <CardTitle>شاخص کل (TEDPIX)</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="text-2xl font-bold">{indexValue.toLocaleString('fa-IR')}</div>
          <div className={`text-sm ${indexChangePercent >= 0 ? 'text-primary' : 'text-destructive'}`}>
            {indexChangePercent >= 0 ? '▲' : '▼'} {Math.abs(indexChangePercent).toFixed(1)}%
          </div>
        </CardContent>
      </Card>
      
      <Card className="card-tarot">
        <CardHeader>
          <CardTitle>شاخص کل هم‌وزن</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="text-2xl font-bold">{eqWeightValue.toLocaleString('fa-IR')}</div>
          <div className={`text-sm ${eqWeightChangePercent >= 0 ? 'text-primary' : 'text-destructive'}`}>
            {eqWeightChangePercent >= 0 ? '▲' : '▼'} {Math.abs(eqWeightChangePercent).toFixed(1)}%
          </div>
        </CardContent>
      </Card>
    </div>
  );
}