// ═══════════════════════════════════════════════════════════════════
// Bedaan6D — Scoring algorithm utilities
// 6-dimensional scoring system with ≥5 sub-metrics per dimension
// Each sub-metric tied to a scientific reference (see references.ts)
// ═══════════════════════════════════════════════════════════════════

export interface DimensionScore {
  key: string;
  name: string;
  weight: number;
  score: number;
  percentage: number;
  color: string;
  subMetrics: SubMetric[];
}

export interface SubMetric {
  name: string;
  value: string | number;
  score: number;
  description: string;
  refId?: string;        // reference ID from references.ts
}

export interface SymbolScore {
  isin: string;
  symbol: string;
  name: string;
  totalScore: number;
  dimensions: DimensionScore[];
}

// ═══════════════════════════════════════════════════════════════════
// Symbol Data — expanded to support ≥5 sub-metrics per dimension
// ═══════════════════════════════════════════════════════════════════
export interface SymbolData {
  isin: string;
  symbol: string;
  name: string;
  market: string;
  sector: string;
  price: number;
  change: number;
  changePercent: number;
  volume: number;
  tradeCount: number;
  buyVolumeHaghighi: number;
  sellVolumeHaghighi: number;
  buyVolumeHoghughi: number;
  sellVolumeHoghughi: number;
  buyCountHaghighi: number;
  sellCountHaghighi: number;
  pe: number;
  eps: number;
  marketCap: number;
  yesterdayPrice: number;
  openPrice: number;
  highPrice: number;
  lowPrice: number;
  closePrice: number;
  queueBuyVolume: number;
  queueSellVolume: number;
  weekTradeVolume: number;
  // ─── Technical indicators (TA-xx) ───
  rsi: number;                  // TA-01: Relative Strength Index (0-100)
  macd: number;                 // TA-02: MACD line
  macdSignal: number;           // TA-02: signal line
  bollingerWidth: number;       // TA-03: Bollinger Bandwidth (%)
  adx: number;                  // TA-09: ADX trend strength (0-100)
  atr: number;                  // TA-10: Average True Range (%)
  obv: number;                  // TA-06: On-Balance Volume (signed)
  // ─── Fundamental indicators (FA-xx) ───
  peg: number;                  // FA-04: PEG ratio
  pb: number;                   // FA-05: Price-to-Book ratio
  roe: number;                  // FA-06: Return on Equity (%)
  debtToEquity: number;         // FA-11: D/E ratio
  freeCashFlowYield: number;    // FA-12: FCF Yield (%)
  intrinsicValue: number;       // FA-01/03: estimated intrinsic value per share
  // ─── Sentiment indicators (SE-xx) ───
  fearGreedIndex: number;       // SE-04: 0-100
  searchVolumeIndex: number;    // SE-10: ASVI relative value
  putCallRatio: number;         // SE-06: PCR
  foreignBuyRatio: number;      // SE-05: foreign buy share (%)
  // ─── Risk indicators (RI-xx) ───
  beta: number;                 // RI-02: beta vs market
  varValue: number;             // RI-05: Value at Risk (%)
  maxDrawdown: number;          // RI-08: MDD (%)
  sortinoRatio: number;         // RI-04: Sortino ratio
  skewness: number;             // RI-09: return skewness
  // ─── Board reading indicators (BO-xx) ───
  bidAskSpread: number;         // BO-01: spread (%)
  orderImbalance: number;       // BO-02: OIR (-1 to +1)
  queueDepth: number;           // BO-03: depth ratio (queue/avg volume)
  amihudIlliquidity: number;    // BO-07: Amihud illiquidity (×1e-9)
  sharesOutstanding: number;    // for turnover computation
}

