'use client';

import { useState, useEffect, useMemo } from 'react';
import { MOCK_SYMBOLS, MOCK_INDICES } from '@/lib/mock-data';
import { computeSymbolScore, SymbolScore, SymbolData, getScoreColor } from '@/lib/scoring';
import { adaptSymbolItems, type BRSSymbolItem } from '@/lib/data-adapter';
import { toPersianNum } from '@/lib/persian';
import { BarChart3, ChevronDown } from 'lucide-react';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Button } from '@/components/ui/button';

type DimensionOption = 'total' | 'technical' | 'fundamental' | 'sentiment' | 'risk' | 'macro' | 'board';

const DIMENSION_OPTIONS: { key: DimensionOption; label: string }[] = [
  { key: 'total', label: 'کل' },
  { key: 'technical', label: 'تکنیکال' },
  { key: 'fundamental', label: 'بنیادی' },
  { key: 'sentiment', label: 'احساسات' },
  { key: 'risk', label: 'ریسک' },
  { key: 'macro', label: 'کلان' },
  { key: 'board', label: 'تابلوخوانی' },
];

function getScoreForDimension(score: SymbolScore, dim: DimensionOption): number {
  if (dim === 'total') return score.totalScore;
  const dimObj = score.dimensions.find(d => d.key === dim);
  return dimObj ? dimObj.score : score.totalScore;
}

export function ScoreTickerBar() {
  const [selectedDim, setSelectedDim] = useState<DimensionOption>('total');
  const [symbols, setSymbols] = useState<SymbolData[]>(MOCK_SYMBOLS);

  useEffect(() => {
    let cancelled = false;
    async function fetchData() {
      try {
        const res = await fetch('/api/market');
        if (!res.ok) return;
        const data = await res.json();
        const raw = data?.data?.symbols || data?.symbols || [];
        if (!cancelled && Array.isArray(raw) && raw.length > 0) {
          const adapted = adaptSymbolItems(raw as BRSSymbolItem[]);
          if (adapted.length > 0) {
            setSymbols(adapted);
          }
        }
      } catch { /* use mock */ }
    }
    fetchData();
    return () => { cancelled = true; };
  }, []);

  const marketChange = MOCK_INDICES[0]?.changePercent || 0;

  const scoredItems = useMemo(() => {
    return symbols.map(s => ({
      symbol: s.symbol,
      score: computeSymbolScore(s, marketChange),
    })).sort((a, b) => getScoreForDimension(b.score, selectedDim) - getScoreForDimension(a.score, selectedDim));
  }, [symbols, selectedDim, marketChange]);

  const tickerItems = [...scoredItems, ...scoredItems];
  const selectedLabel = DIMENSION_OPTIONS.find(d => d.key === selectedDim)?.label || 'کل';

  return (
    <div className="border-b border-border py-1.5 bg-background/80 backdrop-blur-sm relative">
      <div className="container mx-auto px-4">
        <div className="flex items-center gap-2">
          <div className="flex items-center gap-1 shrink-0">
            <BarChart3 className="size-3.5 text-primary" />
            <span className="text-xs font-semibold text-primary">امتیاز</span>
          </div>
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" size="sm" className="h-6 px-2 text-xs gap-1 z-20 text-primary hover:text-accent hover:bg-card">
                {selectedLabel}
                <ChevronDown className="size-3" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="start" className="z-50 bg-card border-border">
              {DIMENSION_OPTIONS.map(opt => (
                <DropdownMenuItem
                  key={opt.key}
                  onClick={() => setSelectedDim(opt.key)}
                  className={selectedDim === opt.key ? 'bg-background text-primary' : 'text-muted-foreground'}
                >
                  {opt.label}
                </DropdownMenuItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>
          <div className="overflow-hidden flex-1">
            <div className="flex w-max gap-6 animate-ticker-scroll whitespace-nowrap">
              {tickerItems.map((item, i) => {
                const dimScore = getScoreForDimension(item.score, selectedDim);
                return (
                  <span key={i} className="inline-flex items-center gap-1.5 text-xs">
                    <span className="font-medium text-muted-foreground">{item.symbol}</span>
                    <span className={`font-bold ${getScoreColor(dimScore)}`}>
                      {toPersianNum(dimScore)}
                    </span>
                  </span>
                );
              })}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
