'use client';

import { useRef, useEffect, useState, useMemo, useCallback } from 'react';
import { DIMENSION_LABELS } from '@/lib/persian';
import { toPersianNum } from '@/lib/persian';
import { Settings, Palette, Move, Play, Pause, RefreshCw } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Slider } from '@/components/ui/slider';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Label } from '@/components/ui/label';

// --- Constants & Types ---
type ColorTheme = 'emerald' | 'sunset' | 'ocean';

interface ThemeColors {
  faceColors: string[];
  borderColors: string[];
  solidBorderColors: string[];
  glowColor: string;
}

const INITIAL_WEIGHTS: number[] = [21, 19, 17, 15, 16, 12]; // sum = 100

// --- Helper Functions ---
function generateRandomWeights(): number[] {
  const raw = Array.from({ length: 6 }, () => 0.5 + Math.random() * 2);
  const sum = raw.reduce((a, b) => a + b, 0);
  const weights = raw.map(r => Math.round((r / sum) * 100));
  const diff = 100 - weights.reduce((a, b) => a + b, 0);
  const maxIdx = weights.indexOf(Math.max(...weights));
  weights[maxIdx] += diff;
  return weights;
}

function getSolidColor(varValue: string): string {
  const m = varValue.match(/\d+/g);
  if (!m) return 'rgba(198, 40, 40, 1)';
  return `rgba(${m[0]}, ${m[1]}, ${m[2]}, 1)`;
}

// --- Sub-Components ---
function ThemeSelector({
  currentTheme,
  onThemeChange,
}: {
  currentTheme: ColorTheme;
  onThemeChange: (theme: ColorTheme) => void;
}) {
  const themeNames: Record<ColorTheme, string> = {
    emerald: 'زمردی',
    sunset: 'غروب',
    ocean: 'اقیانوس',
  };

  return (
    <div className="space-y-2">
      <Label className="text-xs text-muted-foreground flex items-center gap-2">
        <Palette className="size-3" />
        طرح رنگ
      </Label>
      <div className="flex gap-2">
        {(Object.keys({ emerald: true, sunset: true, ocean: true }) as ColorTheme[]).map((theme) => (
          <Button
            key={theme}
            variant={currentTheme === theme ? 'default' : 'outline'}
            size="sm"
            className="text-xs"
            onClick={() => onThemeChange(theme)}
            aria-pressed={currentTheme === theme}
          >
            {themeNames[theme]}
          </Button>
        ))}
      </div>
    </div>
  );
}

function SliderControl({
  label,
  icon: Icon,
  value,
  min,
  max,
  step,
  onChange,
  formatValue,
}: {
  label: string;
  icon: React.ElementType;
  value: number;
  min: number;
  max: number;
  step: number;
  onChange: (val: number) => void;
  formatValue?: (val: number) => string;
}) {
  const displayValue = formatValue ? formatValue(value) : toPersianNum(value);

  return (
    <div className="space-y-2">
      <Label className="text-xs text-muted-foreground flex items-center gap-2">
        <Icon className="size-3" />
        {label}: {displayValue}
      </Label>
      <Slider
        value={[value]}
        min={min}
        max={max}
        step={step}
        onValueChange={(val) => onChange(val[0])}
        aria-label={label}
      />
    </div>
  );
}

function CubeLegend({
  labels,
}: {
  labels: string[];
}) {
  const solidColors = [
    'rgba(198, 40, 40, 1)',
    'rgba(21, 101, 192, 1)',
    'rgba(46, 125, 50, 1)',
    'rgba(255, 213, 79, 1)',
    'rgba(106, 27, 154, 1)',
    'rgba(255, 213, 79, 1)',
  ];
  
  return (
    <div 
      className="flex flex-wrap justify-center gap-5" 
      style={{ marginTop: '80px' }}
      aria-label="راهنمای رنگ‌های مکعب"
    >
      {labels.map((label, i) => (
        <div 
          key={i} 
          className="flex items-center gap-2 text-xs group cursor-default"
        >
          <span
            className="size-2.5 rounded-full shrink-0 group-hover:scale-150 transition-transform duration-300"
            style={{ backgroundColor: solidColors[i] }}
            aria-hidden="true"
          />
          <span className="text-muted-foreground group-hover:text-foreground transition-colors duration-300 font-medium">
            {label}
          </span>
        </div>
      ))}
    </div>
  );
}

// --- Main Component ---
export function LandingCube() {
  // Refs
  const cubeRef = useRef<HTMLDivElement>(null);
  const angleY = useRef(0);
  const angleX = useRef(-25);
  const animRef = useRef<number>(0);
  const lastTime = useRef(0);
  const weightTimer = useRef(0);

  // State
  const [isAnimating, setIsAnimating] = useState(true);
  const [colorTheme, setColorTheme] = useState<ColorTheme>('emerald');
  const [cubeSize, setCubeSize] = useState(180);
  const [rotationSpeed, setRotationSpeed] = useState(10);
  const [glowOpacity, setGlowOpacity] = useState(0.05);
  const [weights, setWeights] = useState(INITIAL_WEIGHTS);

  // Derived values using CSS variables
  const theme = useMemo((): ThemeColors => {
    return {
      emerald: {
        faceColors: [
          'var(--cube-emerald-face-1)',
          'var(--cube-emerald-face-2)',
          'var(--cube-emerald-face-3)',
          'var(--cube-emerald-face-4)',
          'var(--cube-emerald-face-5)',
          'var(--cube-emerald-face-6)',
        ],
        borderColors: [
          'var(--cube-emerald-border-1)',
          'var(--cube-emerald-border-2)',
          'var(--cube-emerald-border-3)',
          'var(--cube-emerald-border-4)',
          'var(--cube-emerald-border-5)',
          'var(--cube-emerald-border-6)',
        ],
        solidBorderColors: [
          'rgba(198, 40, 40, 1)',
          'rgba(21, 101, 192, 1)',
          'rgba(46, 125, 50, 1)',
          'rgba(255, 213, 79, 1)',
          'rgba(106, 27, 154, 1)',
          'rgba(255, 213, 79, 1)',
        ],
        glowColor: 'var(--cube-emerald-glow)',
      },
      sunset: {
        faceColors: [
          'var(--cube-sunset-face-1)',
          'var(--cube-sunset-face-2)',
          'var(--cube-sunset-face-3)',
          'var(--cube-sunset-face-4)',
          'var(--cube-sunset-face-5)',
          'var(--cube-sunset-face-6)',
        ],
        borderColors: [
          'var(--cube-sunset-border-1)',
          'var(--cube-sunset-border-2)',
          'var(--cube-sunset-border-3)',
          'var(--cube-sunset-border-4)',
          'var(--cube-sunset-border-5)',
          'var(--cube-sunset-border-6)',
        ],
        solidBorderColors: [
          'rgba(251, 146, 60, 1)',
          'rgba(252, 211, 77, 1)',
          'rgba(249, 115, 22, 1)',
          'rgba(239, 68, 68, 1)',
          'rgba(244, 114, 182, 1)',
          'rgba(168, 85, 247, 1)',
        ],
        glowColor: 'var(--cube-sunset-glow)',
      },
      ocean: {
        faceColors: [
          'var(--cube-ocean-face-1)',
          'var(--cube-ocean-face-2)',
          'var(--cube-ocean-face-3)',
          'var(--cube-ocean-face-4)',
          'var(--cube-ocean-face-5)',
          'var(--cube-ocean-face-6)',
        ],
        borderColors: [
          'var(--cube-ocean-border-1)',
          'var(--cube-ocean-border-2)',
          'var(--cube-ocean-border-3)',
          'var(--cube-ocean-border-4)',
          'var(--cube-ocean-border-5)',
          'var(--cube-ocean-border-6)',
        ],
        solidBorderColors: [
          'rgba(56, 189, 248, 1)',
          'rgba(34, 211, 238, 1)',
          'rgba(125, 211, 252, 1)',
          'rgba(14, 165, 233, 1)',
          'rgba(37, 99, 235, 1)',
          'rgba(79, 70, 229, 1)',
        ],
        glowColor: 'var(--cube-ocean-glow)',
      },
    }[colorTheme];
  }, [colorTheme]);

  const half = cubeSize / 2;

  // Memoized getTransform for faces
  const getFaceTransform = useCallback((index: number): string => {
    const transforms = [
      `translateZ(${half}px)`,
      `rotateY(180deg) translateZ(${half}px)`,
      `rotateY(90deg) translateZ(${half}px)`,
      `rotateY(-90deg) translateZ(${half}px)`,
      `rotateX(90deg) translateZ(${half}px)`,
      `rotateX(-90deg) translateZ(${half}px)`,
    ];
    return transforms[index];
  }, [half]);

  // Animation loop
  useEffect(() => {
    lastTime.current = performance.now();
    weightTimer.current = 0;

    const animate = (now: number) => {
      if (!isAnimating) {
        animRef.current = requestAnimationFrame(animate);
        return;
      }

      const dt = (now - lastTime.current) / 1000;
      lastTime.current = now;

      // Y-axis: continuous rotation
      angleY.current += rotationSpeed * dt;
      // X-axis: sinusoidal oscillation
      angleX.current = -20 + 35 * Math.sin((now / 16000) * Math.PI * 2);

      if (cubeRef.current) {
        cubeRef.current.style.transform =
          `rotateX(${angleX.current}deg) rotateY(${angleY.current}deg)`;
      }

      // Update random weights every 4 seconds using React state
      weightTimer.current += dt;
      if (weightTimer.current > 4) {
        weightTimer.current = 0;
        setWeights(generateRandomWeights());
      }

      animRef.current = requestAnimationFrame(animate);
    };

    animRef.current = requestAnimationFrame(animate);
    
    return () => {
      if (animRef.current) {
        cancelAnimationFrame(animRef.current);
      }
    };
  }, [isAnimating, rotationSpeed]);

  // Handlers
  const handleRandomize = useCallback(() => {
    setWeights(generateRandomWeights());
  }, []);

  return (
    <div 
      className="flex flex-col items-center justify-start select-none relative" 
      style={{ 
        perspective: '1000px',
        '--cube-glow-opacity': glowOpacity,
      } as React.CSSProperties}
      role="img"
      aria-label="مکعب سه‌بعدی شاخص‌های تحلیلی"
    >
      {/* Soft glow behind cube */}
      <div 
        className="absolute rounded-full blur-3xl transition-all duration-500"
        style={{ 
          width: `${cubeSize + 120}px`,
          height: `${cubeSize + 120}px`,
          backgroundColor: theme.glowColor,
        }} 
        aria-hidden="true"
      />

      {/* Settings Panel */}
      <div className="absolute -top-16 right-0 z-10">
        <Popover>
          <PopoverTrigger asChild>
            <Button variant="ghost" size="icon" className="h-8 w-8" aria-label="تنظیمات مکعب">
              <Settings className="size-4" />
            </Button>
          </PopoverTrigger>
          <PopoverContent className="w-80 mr-4 bg-card border-border text-foreground">
            <div className="space-y-4">
              <h3 className="font-semibold text-sm flex items-center gap-2">
                <Settings className="size-4" />
                تنظیمات مکعب
              </h3>
              
              <ThemeSelector currentTheme={colorTheme} onThemeChange={setColorTheme} />

              <SliderControl
                label="اندازه مکعب"
                icon={Move}
                value={cubeSize}
                min={100}
                max={300}
                step={10}
                onChange={setCubeSize}
                formatValue={(v) => `${toPersianNum(v)}px`}
              />

              <SliderControl
                label="سرعت چرخش"
                icon={RefreshCw}
                value={rotationSpeed}
                min={0}
                max={50}
                step={1}
                onChange={setRotationSpeed}
                formatValue={(v) => `${toPersianNum(v)}°/s`}
              />

              <SliderControl
                label="شدت درخشش"
                icon={Palette}
                value={Math.round(glowOpacity * 100)}
                min={0}
                max={20}
                step={1}
                onChange={(val) => setGlowOpacity(val / 100)}
                formatValue={(v) => `${toPersianNum(v)}%`}
              />

              <div className="flex gap-2">
                <Button
                  variant="outline"
                  size="sm"
                  className="flex-1 text-xs"
                  onClick={() => setIsAnimating(!isAnimating)}
                >
                  {isAnimating ? (
                    <><Pause className="size-3 ml-1" /> توقف</>
                  ) : (
                    <><Play className="size-3 ml-1" /> شروع</>
                  )}
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  className="flex-1 text-xs"
                  onClick={handleRandomize}
                >
                  <RefreshCw className="size-3 ml-1" /> تصادفی
                </Button>
              </div>
            </div>
          </PopoverContent>
        </Popover>
      </div>

      {/* The Cube */}
      <div
        ref={cubeRef}
        className="relative transition-all duration-500"
        style={{
          width: `${cubeSize}px`,
          height: `${cubeSize}px`,
          transformStyle: 'preserve-3d',
        }}
        aria-hidden="false"
      >
        {DIMENSION_LABELS.map((label, i) => (
          <div
            key={i}
            className="absolute inset-0 flex flex-col items-center justify-center rounded-2xl border backdrop-blur-sm transition-colors duration-500"
            style={{
              backgroundColor: theme.faceColors[i],
              borderColor: theme.borderColors[i],
              borderWidth: '1.5px',
              transform: getFaceTransform(i),
            }}
            aria-label={`${label}: ${weights[i]} درصد`}
          >
            <span 
              className="text-[10px] mb-1 tracking-wide font-bold drop-shadow-[0_1px_3px_rgba(0,0,0,0.8)]" 
              style={{ color: getSolidColor(theme.borderColors[i]) }}
            >
              {label}
            </span>
            <span
              className="text-2xl font-black tracking-tight drop-shadow-[0_2px_4px_rgba(0,0,0,0.9)]"
              style={{ color: 'var(--foreground)' }}
            >
              {toPersianNum(weights[i])}٪
            </span>
          </div>
        ))}
      </div>

      {/* Legend below cube */}
      <CubeLegend labels={DIMENSION_LABELS} />
    </div>
  );
}

export default LandingCube;
