'use client';

import { HoverCard, HoverCardTrigger, HoverCardContent } from '@/components/ui/hover-card';
import { SpiderChart } from '@/components/SpiderChart';
import type { SymbolData, SymbolScore } from '@/lib/scoring';
import { getScoreColor } from '@/lib/scoring';
import { toPersianNum } from '@/lib/persian';

interface SymbolHoverCardProps {
  symbol: SymbolData;
  score: SymbolScore;
  children: React.ReactNode;
}

function getSignalInfo(score: number): { label: string; color: string } {
  if (score >= 70) return { label: 'خرید', color: 'var(--chart-4)' };
  if (score >= 50) return { label: 'نگهداری', color: 'var(--chart-3)' };
  if (score >= 30) return { label: 'احتیاط', color: 'var(--chart-2)' };
  return { label: 'فروش', color: 'var(--destructive)' };
}

export function SymbolHoverCard({ symbol, score, children }: SymbolHoverCardProps) {
  const signal = getSignalInfo(score.totalScore);

  return (
    <HoverCard openDelay={300} closeDelay={150}>
      <HoverCardTrigger asChild>
        {children}
      </HoverCardTrigger>
      <HoverCardContent
        side="left"
        align="start"
        className="w-auto p-3 z-50"
        sideOffset={8}
      >
        <div className="flex flex-col gap-2">
          {/* Header */}
          <div className="flex items-center justify-between gap-3">
            <div className="flex flex-col">
              <span className="font-bold text-sm">{symbol.symbol}</span>
              <span className="text-xs text-muted-foreground">{symbol.name}</span>
            </div>
            <div className="flex flex-col items-end gap-0.5">
              <span className={`text-lg font-black ${getScoreColor(score.totalScore)}`}>
                {toPersianNum(score.totalScore)}
              </span>
              <span
                className="text-[10px] font-bold px-1.5 py-0.5 rounded-full"
                style={{
                  backgroundColor: `${signal.color}18`,
                  color: signal.color,
                }}
              >
                {signal.label}
              </span>
            </div>
          </div>

          {/* Price info */}
          <div className="flex items-center gap-3 text-xs text-muted-foreground">
            <span>{toPersianNum(symbol.price.toLocaleString())} ریال</span>
            <span className={symbol.changePercent >= 0 ? 'text-chart-4' : 'text-destructive'}>
              {symbol.changePercent >= 0 ? '▲' : '▼'} {toPersianNum(Math.abs(symbol.changePercent).toFixed(1))}٪
            </span>
          </div>

          {/* Spider chart */}
          <div className="flex justify-center">
            <SpiderChart score={score} size={200} showLabels={true} />
          </div>
        </div>
      </HoverCardContent>
    </HoverCard>
  );
}
