'use client';

import { getScoreColor, getScoreBgColor } from '@/lib/scoring';

interface ScoreCardProps {
  score: number;
  label?: string;
  size?: 'xl' | 'lg' | 'md' | 'sm';
  showGauge?: boolean;
  className?: string;
}

export function ScoreCard({ score, label, size = 'lg', showGauge = true, className = '' }: ScoreCardProps) {
  const colorClass = getScoreColor(score);
  const bgClass = getScoreBgColor(score);

  const sizeClasses = {
    xl: 'text-7xl',
    lg: 'text-5xl',
    md: 'text-3xl',
    sm: 'text-xl',
  };

  const gaugeSize = {
    xl: 120,
    lg: 90,
    md: 60,
    sm: 40,
  };

  const gaugePx = gaugeSize[size] || 90;
  const strokeWidth = gaugePx > 80 ? 8 : 6;
  const radius = (gaugePx - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference - (score / 100) * circumference;

  return (
    <div className={`flex flex-col items-center gap-2 ${className}`}>
      {showGauge && (
        <div className="relative">
          <svg
            width={gaugePx}
            height={gaugePx}
            className="transform rotate-[-90deg]"
          >
            {/* Background circle */}
            <circle
              cx={gaugePx / 2}
              cy={gaugePx / 2}
              r={radius}
              fill="none"
              stroke="currentColor"
              strokeWidth={strokeWidth}
              className="text-muted/30"
            />
            {/* Score arc */}
            <circle
              cx={gaugePx / 2}
              cy={gaugePx / 2}
              r={radius}
              fill="none"
              strokeWidth={strokeWidth}
              strokeLinecap="round"
              strokeDasharray={circumference}
              strokeDashoffset={offset}
              className={`${bgClass} score-gauge-circle`}
              style={{ stroke: 'currentColor' }}
            />
          </svg>
          <div className="absolute inset-0 flex items-center justify-center">
            <span className={`${sizeClasses[size]} ${colorClass} font-bold score-number`}>
              {score}
            </span>
          </div>
        </div>
      )}
      {!showGauge && (
        <span className={`${sizeClasses[size]} ${colorClass} font-bold score-number`}>
          {score}
        </span>
      )}
      {label && (
        <span className="text-sm text-muted-foreground font-medium">{label}</span>
      )}
    </div>
  );
}
