'use client';

import { useSyncExternalStore } from 'react';

function subscribe(callback: () => void) {
  const interval = setInterval(callback, 60000);
  return () => clearInterval(interval);
}

function getSnapshot() {
  const now = new Date();
  const dayName = new Intl.DateTimeFormat('fa-IR', { weekday: 'long' }).format(now);
  const time = new Intl.DateTimeFormat('fa-IR', {
    hour: '2-digit',
    minute: '2-digit',
  }).format(now);
  return `${dayName} ${time}`;
}

function getServerSnapshot() {
  return '';
}

export function LiveClock() {
  const dateTime = useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);

  return (
    <div className="hidden sm:flex items-center gap-2 text-xs text-muted-foreground" suppressHydrationWarning>
      <span>آخرین بروزرسانی:</span>
      <span className="font-medium" suppressHydrationWarning>{dateTime || 'در حال بارگذاری...'}</span>
    </div>
  );
}
