'use client';

import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { SymbolHoverCard } from '@/components/SymbolHoverCard';
import type { SymbolData } from '@/lib/scoring';
import { computeSymbolScore } from '@/lib/scoring';
import { toPersianNum } from '@/lib/persian';

interface IndexData {
  name: string;
  value: number;
  change: number;
  changePercent: number;
  price?: number;
}

interface MarketOverviewProps {
  indices: IndexData[];
  goldCurrency: IndexData[];
}

/* ── Convert index/gold data to a pseudo SymbolData for scoring ── */
function indexToSymbolData(item: IndexData): SymbolData {
  const price = item.price || item.value;
  const pct = item.changePercent || 0;
  const chg = item.change || 0;
  const yesterdayPrice = price - chg;

  return {
    isin: `IDX-${item.name}`,
    symbol: item.name,
    name: item.name,
    market: 'شاخص',
    sector: 'شاخص',
    price,
    change: chg,
    changePercent: pct,
    volume: 0,
    tradeCount: 0,
    buyVolumeHaghighi: 0,
    sellVolumeHaghighi: 0,
    buyVolumeHoghughi: 0,
    sellVolumeHoghughi: 0,
    buyCountHaghighi: 0,
    sellCountHaghighi: 0,
    pe: 0,
    eps: 0,
    marketCap: 0,
    yesterdayPrice: yesterdayPrice > 0 ? yesterdayPrice : price,
    openPrice: price,
    highPrice: price * 1.01,
    lowPrice: price * 0.99,
    closePrice: price,
    queueBuyVolume: 0,
    queueSellVolume: 0,
    weekTradeVolume: 0,
    // Technical (neutral defaults for indices/gold)
    rsi: 50,
    macd: 0,
    macdSignal: 0,
    bollingerWidth: 5,
    adx: 20,
    atr: 2,
    obv: 0,
    // Fundamental (neutral defaults)
    peg: 1.5,
    pb: 2,
    roe: 10,
    debtToEquity: 1,
    freeCashFlowYield: 5,
    intrinsicValue: price,
    // Sentiment (neutral defaults)
    fearGreedIndex: 50,
    searchVolumeIndex: 1,
    putCallRatio: 1,
    foreignBuyRatio: 15,
    // Risk (moderate defaults)
    beta: 1,
    varValue: -2,
    maxDrawdown: 15,
    sortinoRatio: 1,
    skewness: 0,
    // Board (neutral defaults)
    bidAskSpread: 0.5,
    orderImbalance: 0,
    queueDepth: 0,
    amihudIlliquidity: 1,
    sharesOutstanding: 0,
  };
}

export function MarketOverview({ indices, goldCurrency }: MarketOverviewProps) {
  return (
<div className="grid grid-cols-1 md:grid-cols-2 gap-6">
       <Card className="card-tarot">
         <CardHeader className="pb-2">
           <CardTitle className="text-base font-semibold">شاخص‌های بازار</CardTitle>
         </CardHeader>
         <CardContent>
           <div className="space-y-3">
             {indices.map((idx, i) => {
               const symData = indexToSymbolData(idx);
               const score = computeSymbolScore(symData);
               return (
                 <SymbolHoverCard key={i} symbol={symData} score={score}>
                   <div className="flex items-center justify-between py-1.5 border-b last:border-b-0 cursor-pointer hover:bg-accent/30 rounded px-1 transition-colors duration-300 ease-magic">
                     <span className="text-sm font-medium">{idx.name}</span>
                     <div className="flex items-center gap-2">
                       <span className="text-sm font-bold">
                         {new Intl.NumberFormat('fa-IR').format(Math.round(idx.value))}
                       </span>
                       <span className={`text-xs font-medium flex items-center gap-0.5 ${
                         idx.changePercent >= 0 ? 'text-chart-4' : 'text-destructive'
                       }`}>
                         {idx.changePercent >= 0 ? '▲' : '▼'}
                         {toPersianNum(Math.abs(idx.changePercent).toFixed(2))}٪
                       </span>
                     </div>
                   </div>
                 </SymbolHoverCard>
               );
             })}
           </div>
         </CardContent>
       </Card>

       <Card className="card-tarot">
         <CardHeader className="pb-2">
           <CardTitle className="text-base font-semibold">طلا و ارز</CardTitle>
         </CardHeader>
         <CardContent>
           <div className="space-y-3">
             {goldCurrency.map((item, i) => {
               const symData = indexToSymbolData(item);
               const score = computeSymbolScore(symData);
               return (
                 <SymbolHoverCard key={i} symbol={symData} score={score}>
                   <div className="flex items-center justify-between py-1.5 border-b last:border-b-0 cursor-pointer hover:bg-accent/30 rounded px-1 transition-colors duration-300 ease-magic">
                     <span className="text-sm font-medium">{item.name}</span>
                     <div className="flex items-center gap-2">
                       <span className="text-sm font-bold">
                         {new Intl.NumberFormat('fa-IR').format(Math.round(item.price || item.value))}
                       </span>
                       <span className={`text-xs font-medium flex items-center gap-0.5 ${
                         item.changePercent >= 0 ? 'text-chart-4' : 'text-destructive'
                       }`}>
                         {item.changePercent >= 0 ? '▲' : '▼'}
                         {toPersianNum(Math.abs(item.changePercent).toFixed(2))}٪
                       </span>
                     </div>
                   </div>
                 </SymbolHoverCard>
               );
             })}
           </div>
         </CardContent>
       </Card>
     </div>
  );
}
