/**
 * @file hierarchy.ts
 * @description ساختار سلسله‌مراتبی جامع پروژه Bedaan6D
 * ساختار: ۶ بعد اصلی × ۶ زیربعد × ۷ جنبه × ۹ زیرمجموعه
 * مجموع عناصر لایه آخر: ۲۲۶۸
 */

export interface SubCategory {
  id: string;
  name: string;
}

export interface Aspect {
  id: string;
  name: string;
  subCategories: SubCategory[]; // باید دقیقاً ۹ مورد باشد
}

export interface SubDimension {
  id: string;
  name: string;
  aspects: Aspect[]; // باید دقیقاً ۷ مورد باشد
}

export interface MainDimension {
  id: string;
  name: string;
  subDimensions: SubDimension[]; // باید دقیقاً ۶ مورد باشد
}

// تابع کمکی برای ایجاد ساختار منظم
const generateHierarchy = (): MainDimension[] => {
  const mainDimensions = [
    { id: 'TD-01', name: 'تحلیل تکنیکال' },
    { id: 'TD-02', name: 'تحلیل بنیادی' },
    { id: 'TD-03', name: 'احساسات بازار' },
    { id: 'TD-04', name: 'تحلیل ریسک' },
    { id: 'TD-05', name: 'اقتصاد کلان' },
    { id: 'TD-06', name: 'تابلوخوانی' },
  ];

  const subDimensionNames: Record<string, string[]> = {
    'TD-01': ['اندیکاتورهای مومنتوم', 'الگوهای نموداری', 'میانگین‌های متحرک', 'سطوح حمایت و مقاومت', 'تحلیل زمانی', 'نوسان‌گرهای پیشرو'],
    'TD-02': ['تجزیه و تحلیل سودآوری', 'ارزش‌گذاری نسبی', 'ساختار سرمایه', 'جریان وجوه نقد', 'کارایی عملیاتی', 'ارزش ذاتی'],
    'TD-03': ['رفتار معامله‌گران حقیقی', 'فعالیت کدهای حقوقی', 'روانشناسی توده', 'شاخص‌های خوش‌بینی/بدبینی', 'جریان نقدینگی هوشمند', 'شبکه‌های اجتماعی و اخبار'],
    'TD-04': ['ریسک سیستماتیک', 'ریسک نقدینگی', 'نوسان‌پذیری بازده', 'ریسک اعتباری و نکول', 'ریسک عملیاتی شرکت', 'تحلیل حساسیت'],
    'TD-05': ['سیاست‌های پولی و بانکی', 'متغیرهای تورمی', 'بازارهای جهانی و کالا', 'نرخ ارز و بازارهای موازی', 'بودجه و سیاست‌های مالی', 'تولید ناخالص و رشد'],
    'TD-06': ['ریزساختار سفارشات', 'قدرت خریدار و فروشنده', 'تحلیل سرانه معاملات', 'تغییر مالکیت سهام', 'ورود و خروج پول', 'عمق بازار و صف‌ها'],
  };

  return mainDimensions.map((main) => ({
    ...main,
    subDimensions: subDimensionNames[main.id].map((subName, subIdx) => ({
      id: `${main.id}-SUB-${subIdx + 1}`,
      name: subName,
      aspects: Array.from({ length: 7 }, (_, aspIdx) => ({
        id: `${main.id}-SUB-${subIdx + 1}-ASP-${aspIdx + 1}`,
        name: `جنبه ${aspIdx + 1} از ${subName}`,
        subCategories: Array.from({ length: 9 }, (_, catIdx) => ({
          id: `${main.id}-SUB-${subIdx + 1}-ASP-${aspIdx + 1}-CAT-${catIdx + 1}`,
          name: `زیرمجموعه ${catIdx + 1} از جنبه ${aspIdx + 1}`,
        })),
      })),
    })),
  }));
};

export const PROJECT_HIERARCHY = generateHierarchy();

/**
 * تابع اعتبارسنجی برای اطمینان از صحت تعداد عناصر
 */
export const verifyHierarchyCounts = () => {
  const report = {
    mainDimensions: PROJECT_HIERARCHY.length,
    subDimensions: 0,
    aspects: 0,
    subCategories: 0,
  };

  PROJECT_HIERARCHY.forEach(main => {
    report.subDimensions += main.subDimensions.length;
    main.subDimensions.forEach(sub => {
      report.aspects += sub.aspects.length;
      sub.aspects.forEach(asp => {
        report.subCategories += asp.subCategories.length;
      });
    });
  });

  return report;
};
