'use client';

import { useState } from 'react';
import { Download, Loader2, CheckCircle2 } from 'lucide-react';

interface DownloadProjectButtonProps {
  variant?: 'solid' | 'outline';
  className?: string;
}

export function DownloadProjectButton({
  variant = 'outline',
  className = '',
}: DownloadProjectButtonProps) {
  const [status, setStatus] = useState<'idle' | 'loading' | 'done' | 'error'>('idle');

  const handleDownload = async () => {
    if (status === 'loading') return;
    setStatus('loading');
    try {
      const response = await fetch('/api/download-zip');
      if (!response.ok) throw new Error('Download failed');

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'Bedaan6D-project.zip';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      window.URL.revokeObjectURL(url);

      setStatus('done');
      setTimeout(() => setStatus('idle'), 3000);
    } catch (err) {
      console.error(err);
      setStatus('error');
      setTimeout(() => setStatus('idle'), 3000);
    }
  };

  const baseClass =
    'px-4 py-2.5 rounded-lg text-sm font-medium transition-all duration-300 flex items-center gap-2 disabled:opacity-60 disabled:cursor-not-allowed';

  const variantClass =
    variant === 'solid'
      ? 'bg-primary text-primary-foreground hover:bg-primary/90 shadow-lg shadow-primary/10'
      : 'border border-border text-muted-foreground hover:bg-card hover:border-primary/30 hover:text-primary';

  return (
    <button
      onClick={handleDownload}
      disabled={status === 'loading'}
      className={`${baseClass} ${variantClass} ${className}`}
      title="دانلود کل پروژه به صورت فایل فشرده"
    >
      {status === 'loading' ? (
        <>
          <Loader2 className="size-4 animate-spin" />
          <span>در حال ساخت...</span>
        </>
      ) : status === 'done' ? (
        <>
          <CheckCircle2 className="size-4 text-[#34d399]" />
          <span>دانلود شد</span>
        </>
      ) : status === 'error' ? (
        <>
          <Download className="size-4" />
          <span>خطا - دوباره</span>
        </>
      ) : (
        <>
          <Download className="size-4" />
          <span>دانلود پروژه</span>
        </>
      )}
    </button>
  );
}
