// Data adapter: transforms BRS API SymbolItem to our internal SymbolData format
// This bridges the gap between the backend API response and the scoring engine
// NOTE: No Math.random() - all derived values are deterministic based on input data

import type { SymbolData } from './scoring';

/** BRS API SymbolItem format (from brs-types.ts) */
export interface BRSSymbolItem {
  symbol: string;
  name: string;
  isin: string;
  id: number;
  flow: number;
  market: string;
  category: string;
  lastPrice: number;
  yesterdayPrice: number;
  priceChange: number;
  percentChange: number;
  status: string;
  time: string;
}

/** BRS API MarketIndex format */
export interface BRSMarketIndex {
  name: string;
  value: number;
  change: number;
  percentChange: number;
}

/** BRS API GoldCurrencyItem format */
export interface BRSGoldCurrencyItem {
  name: string;
  price: number;
  change: number;
  percentChange: number;
  category: string;
  unit: string;
  updated: string;
}

